// 58: # `ThisFormula`. Homebrew does enforce that the name of the file and the class
// 59: # correspond.
// 60: # Make sure you check with `brew search` that the name is free!
// 61: # @abstract
// 62: # @see SharedEnvExtension
// 63: # @see Pathname
// 64: # @see https://www.rubydoc.info/stdlib/fileutils FileUtils
// 65: # @see https://docs.brew.sh/Formula-Cookbook Formula Cookbook
// 66: # @see https://rubystyle.guide Ruby Style Guide
// 67: #
// 68: # ### Example
// 69: #
// 70: # ```ruby
// 71: # class Wget < Formula
// 72: #   homepage "https://www.gnu.org/software/wget/"
// 73: #   url "https://ftp.gnu.org/gnu/wget/wget-1.15.tar.gz"
// 74: #   sha256 "52126be8cf1bddd7536886e74c053ad7d0ed2aa89b4b630f76785bac21695fcd"
// 75: #
// 76: #   def install
// 77: #     system "./configure", "--prefix=#{prefix}"
// 78: #     system "make", "install"
// 79: #   end
// 80: # end
// 81: # ```
// 82: class Formula
// 83:   include FileUtils
// 84:   include Utils::Shebang
// 85:   include Utils::Shell
// 86:   include Utils::Output::Mixin
// 87:   include Utils::Path
// 88:   include Context
// 89:   include OnSystem::MacOSAndLinux
// 90:   include Homebrew::Livecheck::Constants
// 91:   extend Forwardable
