// 93:   extend Cachable
// 94:   extend APIHashable
// 95:   extend T::Helpers
// 96:   extend Utils::Output::Mixin
// 97:
// 98:   Cache = type_template { { fixed: T::Hash[Symbol, T.untyped] } }
// 99:
// 100:   abstract!
// 101:
// 102:   # Used to track formulae that cannot be installed at the same time.
// 103:   FormulaConflict = Struct.new(:name, :reason)
// 104:
// 105:   SUPPORTED_NETWORK_ACCESS_PHASES = [:build, :test, :postinstall].freeze
// 106:   private_constant :SUPPORTED_NETWORK_ACCESS_PHASES
// 107:   DEFAULT_NETWORK_ACCESS_ALLOWED = true
// 108:   private_constant :DEFAULT_NETWORK_ACCESS_ALLOWED
