// 120:   attr_reader :alias_path
// 121:
// 122:   # The name of the alias that was used to identify this {Formula}.
// 123:   # e.g. `another-name-for-this-formula`
// 124:   sig { returns(T.nilable(String)) }
// 125:   attr_reader :alias_name
