// 235:   # The {BuildOptions} or {Tab} for this {Formula}. Lists the arguments passed
// 236:   # and any {.option}s in the {Formula}. Note that these may differ at
// 237:   # different times during the installation of a {Formula}. This is annoying
// 238:   # but is the result of state that we're trying to eliminate.
// 239:   sig { returns(T.any(BuildOptions, Tab)) }
// 240:   attr_reader :build
