// 258:
// 259:   sig {
// 260:     params(name: String, path: Pathname, spec: Symbol, alias_path: T.nilable(Pathname),
// 261:            tap: T.nilable(Tap), force_bottle: T::Boolean).void
// 262:   }
// 263:   def initialize(name, path, spec, alias_path: nil, tap: nil, force_bottle: false)
// 264:     # Only allow instances of subclasses. The base class does not hold any spec information (URLs etc).
// 265:     raise "Do not call `Formula.new' directly without a subclass." unless self.class < Formula
// 266:     raise "Formula subclasses cannot override `brew`." if self.class.instance_method(:brew).owner != Formula
// 267:
// 268:     # Stop any subsequent modification of a formula's definition.
// 269:     # Changes do not propagate to existing instances of formulae.
// 270:     # Now that we have an instance, it's too late to make any changes to the class-level definition.
// 271:     self.class.freeze
// 272:
// 273:     @name = name
// 274:     @unresolved_path = path
// 275:     @path = T.let(path.resolved_path, Pathname)
// 276:     @alias_path = alias_path
// 277:     @alias_name = T.let((File.basename(alias_path) if alias_path), T.nilable(String))
// 278:     @revision = T.let(self.class.revision || 0, Integer)
// 279:     @version_scheme = T.let(self.class.version_scheme || 0, Integer)
// 280:     @compatibility_version = T.let(self.class.compatibility_version, T.nilable(Integer))
// 281:     @head = T.let(nil, T.nilable(SoftwareSpec))
// 282:     @stable = T.let(nil, T.nilable(SoftwareSpec))
// 283:
// 284:     @autobump = T.let(true, T::Boolean)
// 285:     @no_autobump_message = T.let(nil, T.nilable(T.any(String, Symbol)))
// 286:
// 287:     @force_bottle = force_bottle
// 288:
// 289:     @tap = tap
// 290:     @tap ||= if path == Formulary.core_path(name)
// 291:       CoreTap.instance
// 292:     else
// 293:       Tap.from_path(path)
// 294:     end
// 295:
// 296:     @pypi_packages_info = T.let(self.class.pypi_packages_info || PypiPackages.new, PypiPackages)
// 297:
// 298:     @full_name = T.let(T.must(full_name_with_optional_tap(name)), String)
// 299:     @full_alias_name = T.let(full_name_with_optional_tap(@alias_name), T.nilable(String))
// 300:
// 301:     self.class.spec_syms.each do |sym|
// 302:       spec_eval sym
// 303:     end
// 304:
// 305:     @active_spec = T.let(determine_active_spec(spec), SoftwareSpec)
// 306:     @active_spec_sym = T.let(head? ? :head : :stable, Symbol)
// 307:     validate_attributes!
// 308:     @build = T.let(active_spec.build, T.any(BuildOptions, Tab))
// 309:     @pin = T.let(FormulaPin.new(self), FormulaPin)
// 310:     @follow_installed_alias = T.let(true, T::Boolean)
// 311:     @prefix_returns_versioned_prefix = T.let(false, T.nilable(T::Boolean))
// 312:     @oldname_locks = T.let([], T::Array[FormulaLock])
// 313:     @on_system_blocks_exist = T.let(false, T::Boolean)
// 314:   end
// 315:
// 316:   sig { params(spec_sym: Symbol).void }
// 317:   def active_spec=(spec_sym)
// 318:     spec = send(spec_sym)
// 319:     raise FormulaSpecificationError, "#{spec_sym} spec is not available for #{full_name}" unless spec
// 320:
// 321:     old_spec_sym = @active_spec_sym
// 322:     @active_spec = spec
// 323:     @active_spec_sym = spec_sym
// 324:     validate_attributes!
// 325:     @build = active_spec.build
// 326:
// 327:     return if spec_sym == old_spec_sym
// 328:
// 329:     Dependency.clear_cache
// 330:     Requirement.clear_cache
// 331:   end
// 332:
// 333:   sig { params(build_options: T.any(BuildOptions, Tab)).void }
// 334:   def build=(build_options)
// 335:     old_options = @build
// 336:     @build = build_options
// 337:
// 338:     return if old_options.used_options == build_options.used_options &&
// 339:               old_options.unused_options == build_options.unused_options
// 340:
// 341:     Dependency.clear_cache
// 342:     Requirement.clear_cache
// 343:   end
// 344:
// 345:   # Ensure the given formula is installed.
// 346:   # This is useful for installing a utility formula (e.g. `shellcheck` for `brew style`).
// 347:   # When `executable` is provided, a matching system executable in `ORIGINAL_PATHS`
// 348:   # can satisfy the request without installing the formula. When `latest` is true,
// 349:   # the system executable's version is checked with `version_args` first.
// 350:   # Returns the executable path if `executable` is provided, otherwise the formula.
// 351:   sig {
// 352:     params(
// 353:       reason:           String,
// 354:       latest:           T::Boolean,
// 355:       output_to_stderr: T::Boolean,
// 356:       quiet:            T::Boolean,
// 357:       executable:       T.nilable(String),
// 358:       version_args:     T::Array[String],
// 359:     ).returns(T.any(T.self_type, Pathname))
// 360:   }
// 361:   def ensure_installed!(reason: "", latest: false, output_to_stderr: true, quiet: false, executable: nil,
// 362:                         version_args: ["--version"])
// 363:     if output_to_stderr || quiet
// 364:       file = if quiet
// 365:         File::NULL
// 366:       else
// 367:         $stderr
// 368:       end
// 369:       # Call this method itself with redirected stdout
// 370:       redirect_stdout(file) do
// 371:         return ensure_installed!(latest:, reason:, output_to_stderr: false, executable:, version_args:)
// 372:       end
// 373:     end
// 374:
// 375:     if executable && (system_executable = which(executable, ORIGINAL_PATHS))
// 376:       return system_executable unless latest
// 377:
// 378:       require "system_command"
// 379:       result = SystemCommand.run(system_executable, args: version_args, print_stderr: false)
// 380:       return system_executable if result.success? && result.stdout[/\d+(?:\.\d+)+/] == version.to_s
// 381:     end
// 382:
// 383:     reason = " for #{reason}" if reason.present?
// 384:
// 385:     unless any_version_installed?
// 386:       ohai "Installing `#{name}`#{reason}..."
// 387:       safe_system HOMEBREW_BREW_FILE, "install", "--formula", full_name
// 388:     end
// 389:
// 390:     if latest && !latest_version_installed?
// 391:       ohai "Upgrading `#{name}`#{reason}..."
// 392:       safe_system HOMEBREW_BREW_FILE, "upgrade", "--formula", full_name
// 393:     elsif missing_dependencies.present?
// 394:       ohai "Reinstalling `#{name}`#{reason}..."
// 395:       safe_system HOMEBREW_BREW_FILE, "reinstall", "--formula", full_name
// 396:     end
// 397:
// 398:     executable ? opt_bin/executable : self
// 399:   end
// 400:
// 401:   sig { returns(T::Boolean) }
// 402:   def preserve_rpath? = self.class.preserve_rpath?
// 403:
// 404:   private
// 405:
// 406:   # Allow full name logic to be re-used between names, aliases and installed aliases.
// 407:   sig { params(name: T.nilable(String)).returns(T.nilable(String)) }
// 408:   def full_name_with_optional_tap(name)
// 409:     if name.nil? || @tap.nil? || @tap.core_tap?
// 410:       name
// 411:     else
// 412:       "#{@tap}/#{name}"
// 413:     end
// 414:   end
// 415:
// 416:   sig { params(name: T.any(String, Symbol)).void }
// 417:   def spec_eval(name)
// 418:     spec = self.class.public_send(name).dup
// 419:     return unless spec.url
// 420:
// 421:     spec.owner = self
// 422:     add_global_deps_to_spec(spec)
// 423:     instance_variable_set(:"@#{name}", spec)
// 424:   end
// 425:
// 426:   sig { params(spec: SoftwareSpec).void }
// 427:   def add_global_deps_to_spec(spec); end
// 428:
// 429:   sig { params(requested: T.any(String, Symbol)).returns(SoftwareSpec) }
// 430:   def determine_active_spec(requested)
// 431:     spec = send(requested) || stable || head
// 432:     spec || raise(FormulaSpecificationError, "#{full_name}: formula requires at least a URL")
// 433:   end
// 434:
// 435:   sig { void }
// 436:   def validate_attributes!
// 437:     if name.blank? || name.match?(/\s/) || !Utils.safe_filename?(name)
// 438:       raise FormulaValidationError.new(full_name, :name, name)
// 439:     end
// 440:
// 441:     url = active_spec.url
// 442:     raise FormulaValidationError.new(full_name, :url, url) if url.blank? || url.match?(/\s/)
// 443:
// 444:     val = version.respond_to?(:to_str) ? version.to_str : version
// 445:     return if val.present? && !val.match?(/\s/) && Utils.safe_filename?(val)
// 446:
// 447:     raise FormulaValidationError.new(full_name, :version, val)
// 448:   end
