// 451:
// 452:   # The alias path that was used to install this formula, if it exists.
// 453:   # Can differ from {#alias_path}, which is the alias used to find the formula,
// 454:   # and is specified to this instance.
// 455:   sig { returns(T.nilable(Pathname)) }
// 456:   def installed_alias_path
// 457:     build_tab = build
// 458:     path = build_tab.source["path"] if build_tab.is_a?(Tab)
// 459:
// 460:     return unless path&.match?(%r{#{HOMEBREW_TAP_DIR_REGEX}/Aliases}o)
// 461:
// 462:     path = Pathname(path)
// 463:     return unless path.symlink?
// 464:
// 465:     path
// 466:   end
// 467:
// 468:   sig { returns(T.nilable(String)) }
// 469:   def installed_alias_name = installed_alias_path&.basename&.to_s
// 470:
// 471:   sig { returns(T.nilable(String)) }
// 472:   def full_installed_alias_name = full_name_with_optional_tap(installed_alias_name)
// 473:
// 474:   sig { returns(Tap) }
// 475:   def tap!
// 476:     tap || raise("Formula tap is nil")
// 477:   end
// 478:
// 479:   sig { returns(Pathname) }
// 480:   def tap_path
// 481:     return path unless (t = tap)
// 482:     return Formulary.core_path(name) if t.core_tap?
// 483:     return path unless t.installed?
// 484:
// 485:     t.formula_files_by_name[name] || path
// 486:   end
// 487:
// 488:   # The path that was specified to find this formula.
// 489:   sig { returns(T.nilable(Pathname)) }
// 490:   def specified_path
// 491:     return Homebrew::API::Internal.cached_packages_json_file_path if loaded_from_internal_api?
// 492:     return Homebrew::API::Formula.cached_json_file_path if loaded_from_api?
// 493:     return alias_path if alias_path&.exist?
// 494:
// 495:     return @unresolved_path if @unresolved_path.exist?
// 496:
// 497:     return local_bottle_path if local_bottle_path&.exist?
// 498:
// 499:     alias_path || @unresolved_path
// 500:   end
// 501:
// 502:   sig { returns(T.any(String, Pathname)) }
// 503:   def reloadable_ref = loaded_from_api? ? full_name : path
// 504:
