// 576:   # The date when a human last browsed the homepage.
// 577:   # @!method homepage_browsed
// 578:   # @see .homepage_browsed
// 579:   delegate homepage_browsed: :"self.class"
// 580:
// 581:   # The `livecheck` specification for the software.
// 582:   # @!method livecheck
// 583:   # @see .livecheck
// 584:   delegate livecheck: :"self.class"
