// 592:   # @!method livecheckable?
// 593:   # @see .livecheckable?
// 594:   delegate livecheckable?: :"self.class"
// 595:
// 596:   # Exclude the formula from the autobump list.
// 597:   # @!method no_autobump!
// 598:   # @see .no_autobump!
// 599:   delegate no_autobump!: :"self.class"
// 600:
// 601:   # Is the formula in the autobump list?
// 602:   # @!method autobump?
// 603:   # @see .autobump?
// 604:   delegate autobump?: :"self.class"
// 605:
// 606:   delegate no_autobump_message: :"self.class"
