// 612:
// 613:   # The version for the currently active {SoftwareSpec}.
// 614:   # The version is autodetected from the URL and/or tag so only needs to be
// 615:   # declared if it cannot be autodetected correctly.
// 616:   # @!method version
// 617:   # @see .version
// 618:   delegate version: :active_spec
// 619:
// 620:   delegate [
// 621:     :allow_network_access!,
// 622:     :deny_network_access!,
// 623:     :network_access_allowed?,
// 624:   ] => :"self.class"
