// 645:   delegate post_install_steps: :"self.class"
// 646:
// 647:   sig { void }
// 648:   def update_head_version
// 649:     return unless head?
// 650:
// 651:     head_spec = T.must(head)
// 652:     return unless head_spec.downloader.is_a?(VCSDownloadStrategy)
// 653:     return unless head_spec.downloader.cached_location.exist?
// 654:
// 655:     path = if ENV["HOMEBREW_ENV"]
// 656:       ENV.fetch("PATH")
// 657:     else
// 658:       PATH.new(ORIGINAL_PATHS)
// 659:     end
// 660:
// 661:     with_env(PATH: path) do
// 662:       head_spec.version.update_commit(head_spec.downloader.last_commit)
// 663:     end
// 664:   end
// 665:
// 666:   # The {PkgVersion} for this formula with {version} and {#revision} information.
// 667:   sig { returns(PkgVersion) }
// 668:   def pkg_version = PkgVersion.new(version, revision)
// 669:
// 670:   # If this is a `@`-versioned formula.
// 671:   sig { returns(T::Boolean) }
// 672:   def versioned_formula? = name.include?("@")
// 673:
// 674:   # Returns any other `@`-versioned formulae names for any Formula (including versioned formulae).
// 675:   sig { returns(T::Array[String]) }
// 676:   def versioned_formulae_names
// 677:     name_prefix = unversioned_formula_name || name
// 678:
// 679:     versioned_names = if (formula_tap = tap)
// 680:       formula_tap.prefix_to_versioned_formulae_names.fetch(name_prefix, [])
// 681:     else
// 682:       versioned_formula_glob = if name_prefix.end_with?("-full")
// 683:         "#{name_prefix.delete_suffix("-full")}@*-full.rb"
// 684:       else
// 685:         "#{name_prefix}@*.rb"
// 686:       end
// 687:
// 688:       formula_names_for_glob(versioned_formula_glob)
// 689:     end
// 690:
// 691:     versioned_names.reject do |versioned_name|
// 692:       versioned_name == name
// 693:     end
// 694:   end
// 695:
// 696:   # Returns any `@`-versioned Formula objects for any Formula (including versioned formulae).
// 697:   sig { returns(T::Array[Formula]) }
// 698:   def versioned_formulae
// 699:     versioned_formulae_names.filter_map do |name|
// 700:       Formula[name]
// 701:     rescue FormulaUnavailableError
// 702:       nil
// 703:     end.sort_by(&:version).reverse
// 704:   end
// 705:
// 706:   sig { returns(T.nilable(String)) }
// 707:   def unversioned_formula_name
// 708:     return unless versioned_formula?
// 709:
// 710:     name.sub(/@[\d.]+(?=-full$|$)/, "")
// 711:   end
// 712:
// 713:   sig { params(glob: String).returns(T::Array[String]) }
// 714:   def formula_names_for_glob(glob)
// 715:     @formula_names_for_glob ||= T.let({}, T.nilable(T::Hash[String, T::Array[String]]))
// 716:     @formula_names_for_glob[glob] ||= if (formula_tap = tap)
// 717:       formula_name = File.basename(glob, ".rb")
// 718:       if formula_tap.formula_files_by_name.key?(formula_name)
// 719:         [formula_name]
// 720:       else
// 721:         []
// 722:       end
// 723:     elsif path.exist?
// 724:       Pathname.glob((path.dirname/glob).to_s)
// 725:               .map { |path| path.basename(".rb").to_s }
// 726:               .sort
// 727:     else
// 728:       raise "Either tap or path is required to list sibling formulae"
// 729:     end
// 730:   end
// 731:   private :formula_names_for_glob
// 732:
// 733:   # Returns the sibling `-full` or non-`-full` formula names for any Formula.
// 734:   sig { returns(T::Array[String]) }
// 735:   def full_formulae_names
// 736:     sibling_name = if name.end_with?("-full")
// 737:       name.delete_suffix("-full")
// 738:     else
// 739:       "#{name}-full"
// 740:     end
// 741:
// 742:     formula_names_for_glob("#{sibling_name}.rb")
// 743:   end
// 744:
// 745:   sig { returns(T.nilable(String)) }
// 746:   def link_overwrite_reason
// 747:     installed_overwrite_formulae = link_overwrite_formulae.select(&:any_version_installed?)
// 748:     return if installed_overwrite_formulae.empty?
// 749:
// 750:     reason_formulae = installed_overwrite_formulae.select(&:linked?)
// 751:     status = if reason_formulae.empty?
// 752:       reason_formulae = installed_overwrite_formulae
// 753:       "installed"
// 754:     else
// 755:       "linked"
// 756:     end
// 757:
// 758:     "#{reason_formulae.map(&:full_name).to_sentence} #{reason_formulae.one? ? "is" : "are"} already #{status}"
// 759:   end
// 760:
// 761:   sig { returns(T::Array[String]) }
// 762:   def link_overwrite_related_formula_names
// 763:     [*versioned_formulae_names, *full_formulae_names, unversioned_formula_name].compact
// 764:   end
// 765:
// 766:   # Returns sibling Formula names whose prefix links should be replaced when this Formula is linked.
// 767:   sig { returns(T::Array[String]) }
// 768:   def link_overwrite_formulae_names
// 769:     formula_names = T.let(Set.new, T::Set[String])
// 770:     pending_formula_names = T.let([name], T::Array[String])
// 771:
// 772:     pending_formula_names.each do |current_name|
// 773:       current_formula = begin
// 774:         if current_name == name
// 775:           self
// 776:         else
// 777:           Formula[current_name]
// 778:         end
// 779:       rescue FormulaUnavailableError
// 780:         next
// 781:       end
// 782:
// 783:       current_formula.link_overwrite_related_formula_names.each do |related_formula_name|
// 784:         next if related_formula_name == name
// 785:         next unless formula_names.add?(related_formula_name)
// 786:
// 787:         pending_formula_names << related_formula_name
// 788:       end
// 789:     end
// 790:
// 791:     formula_names.to_a.sort
// 792:   end
// 793:
// 794:   # Returns sibling Formulae whose prefix links should be replaced when this Formula is linked.
// 795:   sig { returns(T::Array[Formula]) }
// 796:   def link_overwrite_formulae
// 797:     link_overwrite_formulae_names.filter_map do |formula_name|
// 798:       Formula[formula_name]
// 799:     rescue FormulaUnavailableError
// 800:       nil
// 801:     end.uniq(&:full_name)
// 802:   end
// 803:
// 804:   sig { params(path: Pathname).returns(T.nilable(T.any(String, Symbol))) }
// 805:   def link_overwrite_keg_name(path)
// 806:     # Don't overwrite files not created by Homebrew.
// 807:     return if path.stat.uid != HOMEBREW_ORIGINAL_BREW_FILE.stat.uid
// 808:
// 809:     keg = Keg.for(path)
// 810:     # This keg doesn't belong to any current core/tap formula, most likely coming from a DIY install.
// 811:     return if keg.tab.tap.nil?
// 812:
// 813:     keg.name
// 814:   rescue NotAKegError, Errno::ENOENT
// 815:     # File doesn't belong to any keg.
// 816:     :missing
// 817:   end
// 818:
// 819:   sig {
// 820:     params(keg_name: T.nilable(T.any(String, Symbol)), overwrite_formulae: T::Array[Formula]).returns(T::Boolean)
// 821:   }
// 822:   def implied_link_overwrite?(keg_name, overwrite_formulae)
// 823:     return false if overwrite_formulae.empty?
// 824:     return false if keg_name.nil?
// 825:
// 826:     case keg_name
// 827:     when :missing
// 828:       # File doesn't belong to any keg, so implied overwrites do not apply.
// 829:       false
// 830:     else
// 831:       overwrite_formulae.any? do |formula|
// 832:         formula.possible_names.include?(keg_name)
// 833:       end
// 834:     end
// 835:   end
// 836:   # Whether this {Formula} is version-synced with other formulae.
// 837:   sig { returns(T::Boolean) }
// 838:   def synced_with_other_formulae?
// 839:     return false if @tap.nil?
// 840:
// 841:     @tap.synced_versions_formulae.any? { |synced_formulae| synced_formulae.include?(name) }
// 842:   end
// 843:
// 844:   # A named {Resource} for the currently active {SoftwareSpec}.
// 845:   # Additional downloads can be defined as {#resource}s.
// 846:   # {Resource#stage} will create a temporary directory and yield to a block.
// 847:   #
// 848:   # ### Example
// 849:   #
// 850:   # ```ruby
// 851:   # resource("additional_files").stage { bin.install "my/extra/tool" }
// 852:   # ```
// 853:   #
// 854:   # FIXME: This should not actually take a block. All resources should be defined
// 855:   #        at the top-level using {Formula.resource} instead
// 856:   #        (see https://github.com/Homebrew/brew/issues/17203#issuecomment-2093654431).
// 857:   #
// 858:   # @api public
// 859:   sig {
// 860:     params(name: String, klass: T.class_of(Resource), block: T.nilable(T.proc.bind(Resource).void))
// 861:       .returns(T.nilable(Resource))
// 862:   }
// 863:   def resource(name = T.unsafe(nil), klass = T.unsafe(nil), &block)
// 864:     if klass.nil?
// 865:       active_spec.resource(*name, &block)
// 866:     else
// 867:       active_spec.resource(name, klass, &block)
// 868:     end
// 869:   end
// 870:
// 871:   # Old names for the formula.
// 872:   #
// 873:   # @api internal
// 874:   sig { returns(T::Array[String]) }
// 875:   def oldnames
// 876:     @oldnames ||= T.let(nil, T.nilable(T::Array[String]))
// 877:     @oldnames ||= if (tap = self.tap)
// 878:       oldnames = Tap.tap_migration_oldnames(tap, name) + tap.formula_reverse_renames.fetch(name, [])
// 879:       oldnames.reject { |oldname| Utils.name_from_full_name(oldname) == name }
// 880:     else
// 881:       []
// 882:     end
// 883:   end
// 884:
// 885:   sig { params(oldnames: T.nilable(T::Array[String])).void }
// 886:   attr_writer :oldnames
// 887:
// 888:   # All aliases for the formula.
// 889:   #
// 890:   # @api internal
// 891:   sig { returns(T::Array[String]) }
// 892:   def aliases
// 893:     @aliases ||= T.let(
// 894:       if (tap = self.tap)
// 895:         tap.alias_reverse_table.fetch(full_name, []).map { Utils.name_from_full_name(it) }
// 896:       else
// 897:         []
// 898:       end, T.nilable(T::Array[String])
// 899:     )
// 900:   end
