// 941:
// 942:   # If this {Formula} is installed.
// 943:   # This is actually just a check for if the {#latest_installed_prefix} directory
// 944:   # exists and is not empty.
// 945:   sig { returns(T::Boolean) }
// 946:   def latest_version_installed?
// 947:     (dir = latest_installed_prefix).directory? && !dir.empty?
// 948:   end
// 949:
// 950:   # If at least one version of {Formula} is installed.
// 951:   #
// 952:   # @api public
// 953:   sig { returns(T::Boolean) }
// 954:   def any_version_installed?
// 955:     installed_prefixes.any? { |keg| (keg/AbstractTab::FILENAME).file? }
// 956:   end
// 957:
// 958:   # The link status symlink directory for this {Formula}.
// 959:   # You probably want {#opt_prefix} instead.
// 960:   #
// 961:   # @api internal
// 962:   sig { returns(Pathname) }
// 963:   def linked_keg
// 964:     linked_keg = possible_names.map { |name| HOMEBREW_LINKED_KEGS/name }
// 965:                                .find(&:directory?)
// 966:     linked_keg || (HOMEBREW_LINKED_KEGS/name)
// 967:   end
// 968:
// 969:   sig { returns(T.nilable(PkgVersion)) }
// 970:   def latest_head_version
// 971:     head_versions = installed_prefixes.filter_map do |pn|
// 972:       pn_pkgversion = PkgVersion.parse(pn.basename.to_s)
// 973:       pn_pkgversion if pn_pkgversion.head?
// 974:     end
// 975:
// 976:     head_versions.max_by do |pn_pkgversion|
// 977:       [Keg.new(prefix(pn_pkgversion)).tab.source_modified_time, pn_pkgversion.revision]
// 978:     end
// 979:   end
// 980:
// 981:   sig { returns(T.nilable(Pathname)) }
// 982:   def latest_head_prefix
// 983:     head_version = latest_head_version
// 984:     prefix(head_version) if head_version
// 985:   end
// 986:
// 987:   sig { params(version: PkgVersion, fetch_head: T::Boolean).returns(T::Boolean) }
// 988:   def head_version_outdated?(version, fetch_head: false)
// 989:     tab = Tab.for_keg(prefix(version))
// 990:
// 991:     return true if tab.version_scheme < version_scheme
// 992:
// 993:     tab_stable_version = tab.stable_version
// 994:     return true if stable && tab_stable_version && tab_stable_version < T.must(stable).version
// 995:     return false unless fetch_head
// 996:     return false unless head&.downloader.is_a?(VCSDownloadStrategy)
// 997:
// 998:     downloader = T.must(head).downloader
// 999:
// 1000:     with_context quiet: true do
// 1001:       downloader.commit_outdated?(version.version.commit)
// 1002:     end
// 1003:   end
// 1004:
// 1005:   sig { params(fetch_head: T::Boolean).returns(PkgVersion) }
// 1006:   def latest_head_pkg_version(fetch_head: false)
// 1007:     return pkg_version unless (latest_version = latest_head_version)
// 1008:     return latest_version unless head_version_outdated?(latest_version, fetch_head:)
// 1009:
// 1010:     downloader = T.must(head).downloader
// 1011:     with_context quiet: true do
// 1012:       PkgVersion.new(Version.new("HEAD-#{downloader.last_commit}"), revision)
// 1013:     end
// 1014:   end
// 1015:
// 1016:   # The latest prefix for this formula. Checks for {#head} and then {#stable}'s {#prefix}.
// 1017:   sig { returns(Pathname) }
// 1018:   def latest_installed_prefix
// 1019:     if head && (head_version = latest_head_version) && !head_version_outdated?(head_version)
// 1020:       T.must(latest_head_prefix)
// 1021:     elsif stable && (stable_prefix = prefix(PkgVersion.new(T.must(stable).version, revision))).directory?
// 1022:       stable_prefix
// 1023:     else
// 1024:       prefix
// 1025:     end
// 1026:   end
// 1027:
// 1028:   # The directory in the Cellar that the formula is installed to.
// 1029:   # This directory points to {#opt_prefix} if it exists and if {#prefix} is not
// 1030:   # called from within the same formula's {#install} or {#post_install} methods.
// 1031:   # Otherwise, return the full path to the formula's keg (versioned Cellar path).
// 1032:   #
// 1033:   # @api public
// 1034:   sig { params(version: T.any(String, PkgVersion)).returns(Pathname) }
// 1035:   def prefix(version = pkg_version)
// 1036:     versioned_prefix = versioned_prefix(version)
// 1037:     version = PkgVersion.parse(version) if version.is_a?(String)
// 1038:     if !@prefix_returns_versioned_prefix && version == pkg_version &&
// 1039:        versioned_prefix.directory? && Keg.new(versioned_prefix).optlinked?
// 1040:       opt_prefix
// 1041:     else
// 1042:       versioned_prefix
// 1043:     end
// 1044:   end
