// 1051:
// 1052:   # Is the formula linked to `opt`?
// 1053:   sig { returns(T::Boolean) }
// 1054:   def optlinked? = opt_prefix.symlink?
// 1055:
// 1056:   # {PkgVersion} of the linked keg for the formula.
// 1057:   sig { returns(T.nilable(PkgVersion)) }
// 1058:   def linked_version
// 1059:     return unless linked?
// 1060:
// 1061:     Keg.for(linked_keg).version
// 1062:   end
