// 1071:   def installed_prefixes = Utils::Path.formula_installed_prefixes(possible_names)
// 1072:
// 1073:   # All currently installed kegs.
// 1074:   sig { returns(T::Array[Keg]) }
// 1075:   def installed_kegs
// 1076:     installed_prefixes.map { |dir| Keg.new(dir) }
// 1077:   end
