// 1586:
// 1587:   sig { void }
// 1588:   def install_etc_var
// 1589:     etc_var_dirs = [bottle_prefix/"etc", bottle_prefix/"var"]
// 1590:     Find.find(*etc_var_dirs.select(&:directory?)) do |path|
// 1591:       path = Pathname.new(path)
// 1592:       # Bottle installs and test-bot cleanup both restore `.bottle` files
// 1593:       # through `InstallRenamed`, matching formula-level `etc.install` handling.
// 1594:       path.extend(InstallRenamed)
// 1595:       path.cp_path_sub(bottle_prefix, HOMEBREW_PREFIX)
// 1596:       path
// 1597:     end
// 1598:   end
// 1599:
// 1600:   sig { void }
// 1601:   def run_post_install_steps
// 1602:     return if post_install_steps.empty?
// 1603:
// 1604:     prefix_returns_versioned_prefix = @prefix_returns_versioned_prefix
// 1605:     @prefix_returns_versioned_prefix = T.let(true, T.nilable(T::Boolean))
// 1606:
// 1607:     begin
// 1608:       with_logging("post_install_steps") do
// 1609:         Homebrew::InstallSteps::Runner.new(context: self).run(post_install_steps)
// 1610:       end
// 1611:     ensure
// 1612:       @prefix_returns_versioned_prefix = prefix_returns_versioned_prefix
// 1613:     end
// 1614:   end
// 1615:
// 1616:   sig { void }
// 1617:   def run_post_install
// 1618:     @prefix_returns_versioned_prefix = T.let(true, T.nilable(T::Boolean))
// 1619:     build = self.build
// 1620:
// 1621:     begin
// 1622:       self.build = Tab.for_formula(self)
// 1623:
// 1624:       new_env = {
// 1625:         TMPDIR:        HOMEBREW_TEMP,
// 1626:         TEMP:          HOMEBREW_TEMP,
// 1627:         TMP:           HOMEBREW_TEMP,
// 1628:         HOMEBREW_PATH: nil,
// 1629:         PATH:          PATH.new(ORIGINAL_PATHS),
// 1630:       }
// 1631:
// 1632:       # Formula post-install creates its isolated HOME inside the child because
// 1633:       # the entire `postinstall.rb` process is already sandboxed by its parent.
// 1634:       Dir.mktmpdir("#{name}-postinstall-", HOMEBREW_TEMP) do |home|
// 1635:         postinstall_home = Pathname(home)
// 1636:         new_env[:HOME] = postinstall_home.to_s
// 1637:         new_env.merge!(common_sandbox_env(postinstall_home))
// 1638:         # Keep postinstall Java temp files in Homebrew temp while the common
// 1639:         # sandbox environment points Java's user home at the cache.
// 1640:         new_env[:_JAVA_OPTIONS] += " -Djava.io.tmpdir=#{HOMEBREW_TEMP}"
// 1641:         setup_home postinstall_home
// 1642:
// 1643:         with_env(new_env) do
// 1644:           ENV.clear_sensitive_environment!
// 1645:           ENV.activate_extensions!
// 1646:
// 1647:           with_logging("post_install") do
// 1648:             run_post_install_steps if post_install_steps_defined?
// 1649:             if post_install_defined?
// 1650:               # odeprecated "`post_install`", "`post_install_steps`"
// 1651:               post_install
// 1652:             end
// 1653:           end
// 1654:         end
// 1655:       end
// 1656:     ensure
// 1657:       self.build = build
// 1658:       @prefix_returns_versioned_prefix = T.let(false, T.nilable(T::Boolean))
// 1659:     end
// 1660:   end
// 1661:
// 1662:   # Warn the user about any Homebrew-specific issues or quirks for this package.
// 1663:   # These should not contain setup instructions that would apply to installation
// 1664:   # through a different package manager on a different OS.
// 1665:   #
// 1666:   # ### Example
// 1667:   #
// 1668:   # ```ruby
// 1669:   # def caveats
// 1670:   #   <<~EOS
// 1671:   #     Are optional. Something the user must be warned about?
// 1672:   #   EOS
// 1673:   # end
// 1674:   # ```
// 1675:   #
// 1676:   # ```ruby
// 1677:   # def caveats
// 1678:   #   s = <<~EOS
// 1679:   #     Print some important notice to the user when `brew info [formula]` is
// 1680:   #     called or when brewing a formula.
// 1681:   #     This is optional. You can use all the vars like #{version} here.
// 1682:   #   EOS
// 1683:   #   s += "Some issue only on older systems" if MacOS.version < :monterey
// 1684:   #   s
// 1685:   # end
// 1686:   # ```
// 1687:   sig { overridable.returns(T.nilable(String)) }
// 1688:   def caveats = nil
// 1689:
// 1690:   # Rarely, you don't want your library symlinked into the main prefix.
// 1691:   # See `gettext.rb` for an example.
// 1692:   # @see .keg_only
// 1693:   #
// 1694:   # @api internal
// 1695:   sig { returns(T::Boolean) }
// 1696:   def keg_only?
// 1697:     return false unless keg_only_reason
// 1698:
// 1699:     keg_only_reason.applicable?
// 1700:   end
// 1701:
// 1702:   delegate keg_only_reason: :"self.class"
// 1703:
// 1704:   # @see .skip_clean
// 1705:   sig { params(path: Pathname).returns(T::Boolean) }
// 1706:   def skip_clean?(path)
// 1707:     return true if path.extname == ".la" && T.must(self.class.skip_clean_paths).include?(:la)
// 1708:
// 1709:     to_check = path.relative_path_from(prefix).to_s
// 1710:     T.must(self.class.skip_clean_paths).include? to_check
// 1711:   end
// 1712:
// 1713:   # @see .link_overwrite
// 1714:   # Explicit `link_overwrite` paths may also be implied for related formula families.
// 1715:   sig { params(path: Pathname).returns(T::Boolean) }
// 1716:   def link_overwrite?(path)
// 1717:     # Don't overwrite files that belong to another keg except when that
// 1718:     # keg's formula is deleted.
// 1719:     case keg_name = link_overwrite_keg_name(path)
// 1720:     when String
// 1721:       begin
// 1722:         f = Formulary.factory(keg_name)
// 1723:       rescue FormulaUnavailableError
// 1724:         # formula for this keg is deleted, so defer to allowlist
// 1725:       rescue TapFormulaAmbiguityError
// 1726:         return false # this keg belongs to another formula
// 1727:       else
// 1728:         # Ensure `keg_name` maps cleanly to the resolved formula via `possible_names`.
// 1729:         return false unless f.possible_names.include?(keg_name)
// 1730:       end
// 1731:     when :missing
// 1732:       # File doesn't belong to any keg, so defer to overwrite checks below.
// 1733:     else
// 1734:       return false
// 1735:     end
// 1736:
// 1737:     to_check = path.relative_path_from(HOMEBREW_PREFIX).to_s
// 1738:     return true if T.must(self.class.link_overwrite_paths).any? do |p|
// 1739:       p.to_s == to_check ||
// 1740:       to_check.start_with?("#{p.to_s.chomp("/")}/") ||
// 1741:       /^#{Regexp.escape(p.to_s).gsub('\*', ".*?")}$/.match?(to_check)
// 1742:     end
// 1743:
// 1744:     implied_link_overwrite?(keg_name, link_overwrite_formulae)
// 1745:   end
