// 1831:   # Applies all patches in the {.patchlist} to the source tree.
// 1832:   #
// 1833:   # @api public
// 1834:   sig { void }
// 1835:   def patch
// 1836:     return if patchlist.empty?
// 1837:
// 1838:     ohai "Patching"
// 1839:     patchlist.each(&:apply)
// 1840:   end
// 1841:
// 1842:   sig { params(is_data: T::Boolean).void }
// 1843:   def selective_patch(is_data: false)
// 1844:     patches = patchlist.select { |p| p.is_a?(DATAPatch) == is_data }
// 1845:     return if patches.empty?
// 1846:
// 1847:     patchtype = if is_data
// 1848:       "DATA"
// 1849:     else
// 1850:       "non-DATA"
// 1851:     end
// 1852:     ohai "Applying #{patchtype} patches"
// 1853:     patches.each(&:apply)
// 1854:   end
// 1855:
// 1856:   # Yields `|self,staging|` with current working directory set to the uncompressed tarball
// 1857:   # where staging is a {Mktemp} staging context.
// 1858:   sig(:final) {
// 1859:     params(fetch: T::Boolean, keep_tmp: T::Boolean, debug_symbols: T::Boolean, interactive: T::Boolean,
// 1860:            _blk: T.proc.params(arg0: Formula, arg1: Mktemp).void).void
// 1861:   }
// 1862:   def brew(fetch: true, keep_tmp: false, debug_symbols: false, interactive: false, &_blk)
// 1863:     @prefix_returns_versioned_prefix = T.let(true, T.nilable(T::Boolean))
// 1864:     active_spec.fetch if fetch
// 1865:     stage(interactive:, debug_symbols:) do |staging|
// 1866:       staging.retain! if keep_tmp || debug_symbols
// 1867:
// 1868:       prepare_patches
// 1869:       fetch_patches if fetch
// 1870:
// 1871:       begin
// 1872:         yield self, staging
// 1873:       rescue
// 1874:         staging.retain! if interactive || debug?
// 1875:         raise
// 1876:       ensure
// 1877:         %w[
// 1878:           config.log
// 1879:           CMakeCache.txt
// 1880:           CMakeConfigureLog.yaml
// 1881:           meson-log.txt
// 1882:         ].each do |logfile|
// 1883:           Dir["**/#{logfile}"].each do |logpath|
// 1884:             destdir = logs/File.dirname(logpath)
// 1885:             mkdir_p destdir
// 1886:             cp logpath, destdir
// 1887:           end
// 1888:         end
// 1889:       end
// 1890:     end
// 1891:   ensure
// 1892:     @prefix_returns_versioned_prefix = T.let(false, T.nilable(T::Boolean))
// 1893:   end
// 1894:
// 1895:   sig { returns(T::Array[String]) }
// 1896:   def lock
// 1897:     @lock = T.let(FormulaLock.new(name), T.nilable(FormulaLock))
// 1898:     T.must(@lock).lock
// 1899:
// 1900:     oldnames.each do |oldname|
// 1901:       next unless (oldname_rack = HOMEBREW_CELLAR/oldname).exist?
// 1902:       next if oldname_rack.resolved_path != rack
// 1903:
// 1904:       oldname_lock = FormulaLock.new(oldname)
// 1905:       oldname_lock.lock
// 1906:       @oldname_locks << oldname_lock
// 1907:     end
// 1908:   end
// 1909:
// 1910:   sig { returns(T::Array[FormulaLock]) }
// 1911:   def unlock
// 1912:     @lock&.unlock
// 1913:     @oldname_locks.each(&:unlock)
// 1914:   end
// 1915:
// 1916:   sig { returns(T::Array[String]) }
// 1917:   def oldnames_to_migrate
// 1918:     oldnames.select do |oldname|
// 1919:       old_rack = HOMEBREW_CELLAR/oldname
// 1920:       next false unless old_rack.directory?
// 1921:       next false if old_rack.subdirs.empty?
// 1922:
// 1923:       tap == Tab.for_keg(old_rack.subdirs.min).tap
// 1924:     end
// 1925:   end
// 1926:
// 1927:   sig { returns(T::Boolean) }
// 1928:   def migration_needed?
// 1929:     !oldnames_to_migrate.empty? && !rack.exist?
// 1930:   end
// 1931:
// 1932:   sig { params(fetch_head: T::Boolean).returns(T::Array[Keg]) }
// 1933:   def outdated_kegs(fetch_head: false)
// 1934:     raise Migrator::MigrationNeededError.new(oldnames_to_migrate.fetch(0), name) if migration_needed?
// 1935:
// 1936:     cache_key = "#{full_name}-#{fetch_head}"
// 1937:     Formula.cache[:outdated_kegs] ||= {}
// 1938:     Formula.cache[:outdated_kegs][cache_key] ||= begin
// 1939:       all_kegs = []
// 1940:       current_version = T.let(false, T::Boolean)
// 1941:       latest = latest_formula
// 1942:
// 1943:       installed_kegs.each do |keg|
// 1944:         all_kegs << keg
// 1945:         version = keg.version
// 1946:         next if version.head?
// 1947:
// 1948:         next if latest.version_scheme > keg.version_scheme && latest.pkg_version != version
// 1949:         next if latest.version_scheme == keg.version_scheme && latest.pkg_version > version
// 1950:
// 1951:         # don't consider this keg current if there's a newer formula available
// 1952:         next if follow_installed_alias? && new_formula_available?
// 1953:
// 1954:         # this keg is the current version of the formula, but only consider it current
// 1955:         # if it's actually linked - an unlinked current version means we're outdated
// 1956:         next if !keg.optlinked? && !keg.linked? && !pinned?
// 1957:
// 1958:         current_version = true
// 1959:         break
// 1960:       end
// 1961:
// 1962:       if current_version ||
// 1963:          ((head_version = latest_head_version) && !head_version_outdated?(head_version, fetch_head:))
// 1964:         []
// 1965:       else
// 1966:         all_kegs += old_installed_formulae.flat_map(&:installed_kegs)
// 1967:         all_kegs.sort_by(&:scheme_and_version)
// 1968:       end
// 1969:     end
// 1970:   end
// 1971:
// 1972:   sig { returns(T::Boolean) }
// 1973:   def new_formula_available?
// 1974:     installed_alias_target_changed? && !latest_formula.latest_version_installed?
// 1975:   end
// 1976:
// 1977:   sig { returns(T.nilable(Formula)) }
// 1978:   def current_installed_alias_target
// 1979:     Formulary.factory(T.must(full_installed_alias_name)) if installed_alias_path
// 1980:   end
// 1981:
// 1982:   # Has the target of the alias used to install this formula changed?
// 1983:   # Returns false if the formula wasn't installed with an alias.
// 1984:   sig { returns(T::Boolean) }
// 1985:   def installed_alias_target_changed?
// 1986:     target = current_installed_alias_target
// 1987:     return false unless target
// 1988:
// 1989:     target.name != name
// 1990:   end
// 1991:
// 1992:   # Is this formula the target of an alias used to install an old formula?
// 1993:   sig { returns(T::Boolean) }
// 1994:   def supersedes_an_installed_formula? = old_installed_formulae.any?
// 1995:
// 1996:   # Has the alias used to install the formula changed, or are different
// 1997:   # formulae already installed with this alias?
// 1998:   sig { returns(T::Boolean) }
// 1999:   def alias_changed?
// 2000:     installed_alias_target_changed? || supersedes_an_installed_formula?
// 2001:   end
// 2002:
// 2003:   # If the alias has changed value, return the new formula.
// 2004:   # Otherwise, return the latest version of the current formula.
// 2005:   sig { returns(Formula) }
// 2006:   def latest_formula
// 2007:     installed_alias_target_changed? ? T.must(current_installed_alias_target) : self
// 2008:   end
// 2009:
// 2010:   sig { returns(T::Array[Formula]) }
// 2011:   def old_installed_formulae
// 2012:     # If this formula isn't the current target of the alias,
// 2013:     # it doesn't make sense to say that other formulae are older versions of it
// 2014:     # because we don't know which came first.
// 2015:     return [] if alias_path.nil? || installed_alias_target_changed?
// 2016:
// 2017:     self.class.installed_with_alias_path(alias_path).reject { |f| f.name == name }
// 2018:   end
// 2019:
// 2020:   # Check whether the installed formula is outdated.
// 2021:   #
// 2022:   # @api internal
// 2023:   sig { params(fetch_head: T::Boolean).returns(T::Boolean) }
// 2024:   def outdated?(fetch_head: false)
// 2025:     !outdated_kegs(fetch_head:).empty?
// 2026:   rescue Migrator::MigrationNeededError
// 2027:     true
// 2028:   end
