// 2069:
// 2070:   # Standard parameters for Cabal-v2 builds.
// 2071:   #
// 2072:   # @api public
// 2073:   # @param installdir directory for `--installdir`. Set to false if using v2-configure or v2-build
// 2074:   sig { params(installdir: T.any(String, Pathname, FalseClass)).returns(T::Array[String]) }
// 2075:   def std_cabal_v2_args(installdir: bin)
// 2076:     # cabal-install's dependency-resolution backtracking strategy can
// 2077:     # easily need more than the default 2,000 maximum number of
// 2078:     # "backjumps," since Hackage is a fast-moving, rolling-release
// 2079:     # target. The highest known needed value by a formula was 43,478
// 2080:     # for git-annex, so 100,000 should be enough to avoid most
// 2081:     # gratuitous backjumps build failures.
// 2082:     args = ["--jobs=#{ENV.make_jobs}", "--max-backjumps=100000"]
// 2083:     args += ["--install-method=copy", "--installdir=#{installdir}"] if installdir
// 2084:     args
// 2085:   end
