// 2117:   def std_cmake_args(install_prefix: prefix, install_libdir: "lib", find_framework: "LAST")
// 2118:     %W[
// 2119:       -DCMAKE_INSTALL_PREFIX=#{install_prefix}
// 2120:       -DCMAKE_INSTALL_LIBDIR=#{install_libdir}
// 2121:       -DCMAKE_BUILD_TYPE=Release
// 2122:       -DCMAKE_FIND_FRAMEWORK=#{find_framework}
// 2123:       -DCMAKE_VERBOSE_MAKEFILE=ON
// 2124:       -DCMAKE_PROJECT_TOP_LEVEL_INCLUDES=#{HOMEBREW_LIBRARY_PATH}/cmake/trap_fetchcontent_provider.cmake
// 2125:       -Wno-dev
