// 2144:
// 2145:   # Standard parameters for Go builds.
// 2146:   #
// 2147:   # ### Example
// 2148:   #
// 2149:   # A special `ldflags` value of `:goreleaser` will output ldflags similar to GoReleaser's
// 2150:   # defaults listed at https://goreleaser.com/customization/builds/builders/go/#options.
// 2151:   # This uses formula metadata so it should not be used inside staged resources.
// 2152:   #
// 2153:   # ```ruby
// 2154:   # std_go_args(ldflags: :goreleaser)
// 2155:   # ```
// 2156:   #
// 2157:   # @api public
// 2158:   sig {
// 2159:     params(
// 2160:       output:  T.any(String, Pathname),
// 2161:       ldflags: T.nilable(T.any(String, T::Array[String], Symbol)),
// 2162:       gcflags: T.nilable(T.any(String, T::Array[String])),
// 2163:       tags:    T.nilable(T.any(String, T::Array[String])),
// 2164:     ).returns(T::Array[String])
// 2165:   }
// 2166:   def std_go_args(output: bin/name, ldflags: nil, gcflags: nil, tags: nil)
// 2167:     case ldflags
// 2168:     when :goreleaser
// 2169:       # If building from a git archive, we use the tap owner as a placeholder.
// 2170:       # This can help upstream identify the exact code that was used in binary.
// 2171:       built_by = tap&.user || "Homebrew"
// 2172:       repo = buildpath
// 2173:       commit = Utils.git_head(repo, safe: false) if repo
// 2174:       commit ||= built_by
// 2175:       ldflags = %W[
// 2176:         -X 'main.version=#{version}'
// 2177:         -X 'main.commit=#{commit}'
// 2178:         -X 'main.date=#{time.iso8601}'
// 2179:         -X 'main.builtBy=#{built_by}'
// 2180:       ]
// 2181:     when Symbol
// 2182:       raise ArgumentError, "Invalid ldflags: #{ldflags.inspect}"
// 2183:     end
// 2184:
// 2185:     ldflags = ["-s", "-w"].concat(Array(ldflags)) unless ENV.debug_symbols?
// 2186:
// 2187:     args = ["-trimpath", "-o=#{output}"]
// 2188:     args << "-tags=#{Array(tags).join(",")}" if tags
// 2189:     args << "-ldflags=#{Array(ldflags).join(" ")}" if ldflags
// 2190:     args << "-gcflags=#{Array(gcflags).join(" ")}" if gcflags
// 2191:     args
// 2192:   end
