// 2197:   sig { params(prefix: T.any(String, Pathname), libdir: T.any(String, Pathname)).returns(T::Array[String]) }
// 2198:   def std_meson_args(prefix: self.prefix, libdir: "lib")
// 2199:     ["--prefix=#{prefix}", "--libdir=#{libdir}", "--buildtype=release", "--wrap-mode=nofallback"]
// 2200:   end
