// 2241:   # Standard parameters for Zig builds.
// 2242:   #
// 2243:   # `release_mode` can be set to either `:safe`, `:fast` or `:small`,
// 2244:   # with `:fast` being the default value.
// 2245:   #
// 2246:   # @api public
// 2247:   sig {
// 2248:     params(
// 2249:       prefix:       T.any(String, Pathname),
// 2250:       release_mode: Symbol,
// 2251:       cpu:          T.nilable(Symbol),
// 2252:     ).returns(T::Array[String])
// 2253:   }
// 2254:   def std_zig_args(prefix: self.prefix, release_mode: :fast, cpu: nil)
// 2255:     raise ArgumentError, "Invalid Zig release mode: #{release_mode}" if [:safe, :fast, :small].exclude?(release_mode)
// 2256:
// 2257:     cpu ||= Hardware.zig_cpu(ENV.effective_arch)
// 2258:     release_mode_downcased = release_mode.to_s.downcase
// 2259:     release_mode_capitalized = release_mode.to_s.capitalize
// 2260:     [
// 2261:       "--prefix", prefix.to_s,
// 2262:       "--release=#{release_mode_downcased}",
// 2263:       "-Doptimize=Release#{release_mode_capitalized}",
// 2264:       "--summary", "all",
// 2265:       "-Dcpu=#{cpu}"
// 2266:     ]
// 2267:   end
// 2268:
// 2269:   # Shared library names according to platform conventions.
// 2270:   #
// 2271:   # Optionally specify a `version` to restrict the shared library to a specific
// 2272:   # version. The special string "*" matches any version.
// 2273:   #
// 2274:   # If `name` is specified as "*", match any shared library of any version.
// 2275:   #
// 2276:   # ### Example
// 2277:   #
// 2278:   # ```ruby
// 2279:   # shared_library("foo")      #=> foo.dylib
// 2280:   # shared_library("foo", 1)   #=> foo.1.dylib
// 2281:   # shared_library("foo", "*") #=> foo.2.dylib, foo.1.dylib, foo.dylib
// 2282:   # shared_library("*")        #=> foo.dylib, bar.dylib
// 2283:   # ```
// 2284:   #
// 2285:   # @api public
// 2286:   sig { params(name: String, version: T.nilable(T.any(String, Integer))).returns(String) }
// 2287:   def shared_library(name, version = nil)
// 2288:     return "*.dylib" if name == "*" && (version.blank? || version == "*")
// 2289:
// 2290:     infix = if version == "*"
// 2291:       "{,.*}"
// 2292:     elsif version.present?
// 2293:       ".#{version}"
// 2294:     end
// 2295:     "#{name}#{infix}.dylib"
// 2296:   end
// 2297:
// 2298:   # Executable/Library RPATH according to platform conventions.
// 2299:   #
// 2300:   # Optionally specify a `source` or `target` depending on the location
// 2301:   # of the file containing the RPATH command and where its target is located.
// 2302:   #
// 2303:   # ### Example
// 2304:   #
// 2305:   # ```ruby
// 2306:   # rpath #=> "@loader_path/../lib"
// 2307:   # rpath(target: frameworks) #=> "@loader_path/../Frameworks"
// 2308:   # rpath(source: libexec/"bin") #=> "@loader_path/../../lib"
// 2309:   # ```
// 2310:   #
// 2311:   # @api public
// 2312:   sig { params(source: Pathname, target: Pathname).returns(String) }
// 2313:   def rpath(source: bin, target: lib)
// 2314:     unless target.to_s.start_with?(HOMEBREW_PREFIX)
// 2315:       raise "rpath `target` should only be used for paths inside `$HOMEBREW_PREFIX`!"
// 2316:     end
// 2317:
// 2318:     "#{loader_path}/#{target.relative_path_from(source)}"
// 2319:   end
// 2320:
// 2321:   # Linker variable for the directory containing the program or shared object.
// 2322:   #
// 2323:   # @api public
// 2324:   sig { returns(String) }
// 2325:   def loader_path = "@loader_path"
// 2326:
// 2327:   # Creates a new `Time` object for use in the formula as the build time.
// 2328:   #
// 2329:   # @see https://www.rubydoc.info/stdlib/time/Time Time
// 2330:   sig { returns(Time) }
// 2331:   def time
// 2332:     if ENV["SOURCE_DATE_EPOCH"].present?
// 2333:       Time.at(ENV["SOURCE_DATE_EPOCH"].to_i).utc
// 2334:     else
// 2335:       Time.now.utc
// 2336:     end
// 2337:   end
// 2338:
// 2339:   # Changes the dynamic library ID of one Mach-O file and codesigns it on
// 2340:   # Apple Silicon. The source and new ID are both explicit. Set
// 2341:   # `resolve_source: true` to edit the target of a source symlink.
// 2342:   #
// 2343:   # ### Examples
// 2344:   #
// 2345:   # ```ruby
// 2346:   # change_dylib_id lib/"libfoo.dylib", opt_lib/"libfoo.dylib"
// 2347:   # change_dylib_id lib/"libfoo.dylib", "@rpath/libfoo.1.dylib", resolve_source: true
// 2348:   # ```
// 2349:   #
// 2350:   # @api public
// 2351:   sig {
// 2352:     params(
// 2353:       file:           Pathname,
// 2354:       id:             T.any(String, Pathname),
// 2355:       resolve_source: T::Boolean,
// 2356:     ).void
// 2357:   }
// 2358:   def change_dylib_id(file, id, resolve_source: false)
// 2359:     Homebrew::InstallSteps.change_dylib_id(file, id, resolve_source:)
// 2360:   end
// 2361:
// 2362:   # Replaces a universal binary with its native slice.
// 2363:   #
// 2364:   # If called with no parameters, does this with all compatible
// 2365:   # universal binaries in a {Formula}'s {Keg}.
// 2366:   #
// 2367:   # Raises an error if no universal binaries are found to deuniversalize.
// 2368:   #
// 2369:   # @api public
// 2370:   sig { params(targets: T.nilable(T.any(Pathname, String))).void }
// 2371:   def deuniversalize_machos(*targets)
// 2372:     if targets.none?
// 2373:       targets = any_installed_keg&.mach_o_files&.select do |file|
// 2374:         file.arch == :universal && file.archs.include?(Hardware::CPU.arch)
// 2375:       end
// 2376:     end
// 2377:
// 2378:     raise "No universal binaries found to deuniversalize" if targets.blank?
// 2379:
// 2380:     targets.compact.each do |target|
// 2381:       target = MachOPathname.wrap(target)
// 2382:       extract_macho_slice_from(target, Hardware::CPU.arch)
// 2383:     end
// 2384:   end
// 2385:
// 2386:   sig { params(file: MachOShim, arch: T.nilable(Symbol)).void }
// 2387:   def extract_macho_slice_from(file, arch = Hardware::CPU.arch)
// 2388:     odebug "Extracting #{arch} slice from #{file}"
// 2389:     file.ensure_writable do
// 2390:       macho = MachO::FatFile.new(file)
// 2391:       native_slice = macho.extract(Hardware::CPU.arch)
// 2392:       native_slice.write file
// 2393:       MachO.codesign! file if Hardware::CPU.arm?
// 2394:     rescue MachO::MachOBinaryError
// 2395:       onoe "#{file} is not a universal binary"
// 2396:       raise
// 2397:     rescue NoMethodError
// 2398:       onoe "#{file} does not contain an #{arch} slice"
// 2399:       raise
// 2400:     end
// 2401:   end
// 2402:   private :extract_macho_slice_from
// 2403:
// 2404:   # Generate shell completions for a formula for `bash`, `zsh`, `fish`, and
// 2405:   # optionally `pwsh` using the formula's executable.
// 2406:   #
// 2407:   # ### Examples
// 2408:   #
// 2409:   # Using default values for optional arguments.
// 2410:   #
// 2411:   # ```ruby
// 2412:   # generate_completions_from_executable(bin/"foo", "completions")
// 2413:   #
// 2414:   # # translates to
// 2415:   # (bash_completion/"foo").write Utils.safe_popen_read({ "SHELL" => "bash" }, bin/"foo", "completions", "bash")
// 2416:   # (zsh_completion/"_foo").write Utils.safe_popen_read({ "SHELL" => "zsh" }, bin/"foo", "completions", "zsh")
// 2417:   # (fish_completion/"foo.fish").write Utils.safe_popen_read({ "SHELL" => "fish" }, bin/"foo",
// 2418:   #                                                          "completions", "fish")
// 2419:   # ```
// 2420:   #
// 2421:   # If your executable can generate completions for PowerShell,
// 2422:   # you must pass ":pwsh" explicitly along with any other supported shells.
// 2423:   # This will pass "powershell" as the completion argument.
// 2424:   #
// 2425:   # ```ruby
// 2426:   # generate_completions_from_executable(bin/"foo", "completions", shells: [:bash, :pwsh])
// 2427:   #
// 2428:   # # translates to
// 2429:   # (bash_completion/"foo").write Utils.safe_popen_read({ "SHELL" => "bash" }, bin/"foo", "completions", "bash")
// 2430:   # (pwsh_completion/"foo").write Utils.safe_popen_read({ "SHELL" => "pwsh" }, bin/"foo",
// 2431:   #                                                           "completions", "powershell")
// 2432:   # ```
// 2433:   #
// 2434:   # Selecting shells and using a different `base_name`.
// 2435:   #
// 2436:   # ```ruby
// 2437:   # generate_completions_from_executable(bin/"foo", "completions", shells: [:bash, :zsh], base_name: "bar")
// 2438:   #
// 2439:   # # translates to
// 2440:   # (bash_completion/"bar").write Utils.safe_popen_read({ "SHELL" => "bash" }, bin/"foo", "completions", "bash")
// 2441:   # (zsh_completion/"_bar").write Utils.safe_popen_read({ "SHELL" => "zsh" }, bin/"foo", "completions", "zsh")
// 2442:   # ```
// 2443:   #
// 2444:   # Using predefined `shell_parameter_format :arg`.
// 2445:   #
// 2446:   # ```ruby
// 2447:   # generate_completions_from_executable(bin/"foo", "completions", shell_parameter_format: :arg, shells: [:bash])
// 2448:   #
// 2449:   # # translates to
// 2450:   # (bash_completion/"foo").write Utils.safe_popen_read({ "SHELL" => "bash" }, bin/"foo",
// 2451:   #                                                     "completions", "--shell=bash")
// 2452:   # ```
// 2453:   #
// 2454:   # Using predefined `shell_parameter_format :clap`.
// 2455:   #
// 2456:   # ```ruby
// 2457:   # generate_completions_from_executable(bin/"foo", shell_parameter_format: :clap, shells: [:zsh])
// 2458:   #
// 2459:   # # translates to
// 2460:   # (zsh_completion/"_foo").write Utils.safe_popen_read({ "SHELL" => "zsh", "COMPLETE" => "zsh" }, bin/"foo")
// 2461:   # ```
// 2462:   #
// 2463:   # Using predefined `shell_parameter_format :click`.
// 2464:   #
// 2465:   # ```ruby
// 2466:   # generate_completions_from_executable(bin/"foo", shell_parameter_format: :click, shells: [:zsh])
// 2467:   #
// 2468:   # # translates to
// 2469:   # (zsh_completion/"_foo").write Utils.safe_popen_read({ "SHELL" => "zsh", "_FOO_COMPLETE" => "zsh_source" },
// 2470:   #                                                     bin/"foo")
// 2471:   # ```
// 2472:   #
// 2473:   # Using predefined `shell_parameter_format :cobra`.
// 2474:   #
// 2475:   # ```ruby
// 2476:   # generate_completions_from_executable(bin/"foo", shell_parameter_format: :cobra, shells: [:bash])
// 2477:   #
// 2478:   # # translates to
// 2479:   # (bash_completion/"foo").write Utils.safe_popen_read({ "SHELL" => "bash" }, bin/"foo", "completion", "bash")
// 2480:   # ```
// 2481:   #
// 2482:   # Using predefined `shell_parameter_format :flag`.
// 2483:   #
// 2484:   # ```ruby
// 2485:   # generate_completions_from_executable(bin/"foo", "completions", shell_parameter_format: :flag, shells: [:bash])
// 2486:   #
// 2487:   # # translates to
// 2488:   # (bash_completion/"foo").write Utils.safe_popen_read({ "SHELL" => "bash" }, bin/"foo", "completions", "--bash")
// 2489:   # ```
// 2490:   #
// 2491:   # Using predefined `shell_parameter_format :none`.
// 2492:   #
// 2493:   # ```ruby
// 2494:   # generate_completions_from_executable(bin/"foo", "completions", shell_parameter_format: :none, shells: [:bash])
// 2495:   #
// 2496:   # # translates to
// 2497:   # (bash_completion/"foo").write Utils.safe_popen_read({ "SHELL" => "bash" }, bin/"foo", "completions")
// 2498:   # ```
// 2499:   #
// 2500:   # Using predefined `shell_parameter_format :typer`.
// 2501:   #
// 2502:   # ```ruby
// 2503:   # generate_completions_from_executable(bin/"foo", shell_parameter_format: :typer, shells: [:zsh])
// 2504:   #
// 2505:   # # translates to
// 2506:   # (zsh_completion/"_foo").write Utils.safe_popen_read(
// 2507:   #   { "SHELL" => "zsh", "_TYPER_COMPLETE_TEST_DISABLE_SHELL_DETECTION" => "1" },
// 2508:   #   bin/"foo", "--show-completion", "zsh"
// 2509:   # )
// 2510:   # ```
// 2511:   #
// 2512:   # Using custom `shell_parameter_format`.
// 2513:   #
// 2514:   # ```ruby
// 2515:   # generate_completions_from_executable(bin/"foo", "completions", shell_parameter_format: "--selected-shell=",
// 2516:   #                                      shells: [:bash])
// 2517:   #
// 2518:   # # translates to
// 2519:   # (bash_completion/"foo").write Utils.safe_popen_read({ "SHELL" => "bash" }, bin/"foo",
// 2520:   #                                                     "completions", "--selected-shell=bash")
// 2521:   # ```
// 2522:   #
// 2523:   # @api public
// 2524:   # @param commands
// 2525:   #   the path to the executable and any passed subcommand(s) to use for generating the completion scripts.
// 2526:   # @param base_name
// 2527:   #   the base name of the generated completion script. Defaults to the name of the executable if installed
// 2528:   #   within formula's bin or sbin. Otherwise falls back to the formula name.
// 2529:   # @param shell_parameter_format
// 2530:   #   specify how `shells` should each be passed to the `executable`. Takes either a String representing a
// 2531:   #   prefix, or one of `[:arg, :clap, :click, :cobra, :flag, :none, :typer]`.
// 2532:   #   Defaults to plainly passing the shell.
// 2533:   # @param shells
// 2534:   #   the shells to generate completion scripts for. Defaults to `[:bash, :zsh, :fish]`.
// 2535:   sig {
// 2536:     params(
// 2537:       commands:               T.any(Pathname, String),
// 2538:       base_name:              T.nilable(String),
// 2539:       shell_parameter_format: T.nilable(T.any(Symbol, String)),
// 2540:       shells:                 T::Array[Symbol],
// 2541:     ).void
// 2542:   }
// 2543:   def generate_completions_from_executable(*commands,
// 2544:                                            base_name: nil,
// 2545:                                            shell_parameter_format: nil,
// 2546:                                            shells: Utils::ShellCompletion.default_completion_shells(shell_parameter_format))
// 2547:     executable = commands.first.to_s
// 2548:     base_name ||= File.basename(executable) if executable.start_with?(bin.to_s, sbin.to_s)
// 2549:     base_name ||= name
// 2550:
// 2551:     completion_script_path_map = {
// 2552:       bash: bash_completion/base_name,
// 2553:       zsh:  zsh_completion/"_#{base_name}",
// 2554:       fish: fish_completion/"#{base_name}.fish",
// 2555:       pwsh: pwsh_completion/"_#{base_name}.ps1",
// 2556:     }
// 2557:
// 2558:     shells.each do |shell|
// 2559:       popen_read_env = { "SHELL" => shell.to_s }
// 2560:       script_path = completion_script_path_map[shell]
// 2561:
// 2562:       shell_parameter = Utils::ShellCompletion.completion_shell_parameter(
// 2563:         shell_parameter_format,
// 2564:         shell,
// 2565:         executable,
// 2566:         popen_read_env,
// 2567:       )
// 2568:
// 2569:       script_path.dirname.mkpath
// 2570:       script_path.write Utils::ShellCompletion.generate_completion_output(commands, shell_parameter, popen_read_env)
// 2571:     end
// 2572:   end
