// 2599:
// 2600:   # An array of all {Formula} names, which the tap formulae have as the fully-qualified name.
// 2601:   sig { returns(T::Array[String]) }
// 2602:   def self.full_names
// 2603:     @full_names ||= T.let(core_names + tap_names, T.nilable(T::Array[String]))
// 2604:   end
// 2605:
// 2606:   # An array of each known {Formula}.
// 2607:   # Can only be used when users set `HOMEBREW_REQUIRE_TAP_TRUST=1` or `HOMEBREW_NO_REQUIRE_TAP_TRUST=1`.
// 2608:   sig { params(eval_all: T::Boolean).returns(T::Array[Formula]) }
// 2609:   def self.all(eval_all: false)
// 2610:     if !eval_all && !Homebrew::EnvConfig.tap_trust_configured?
// 2611:       raise ArgumentError,
// 2612:             "Formula#all cannot be used without `HOMEBREW_REQUIRE_TAP_TRUST=1` or " \
// 2613:             "`HOMEBREW_NO_REQUIRE_TAP_TRUST=1`"
// 2614:     end
// 2615:
// 2616:     trusted_tap_files = Homebrew::Trust.trusted_formula_files(tap_files)
// 2617:
// 2618:     (core_names + trusted_tap_files).filter_map do |name_or_file|
// 2619:       Formulary.factory(name_or_file)
// 2620:     rescue FormulaUnavailableError, FormulaUnreadableError, FormulaSpecificationError => e
// 2621:       # Don't let one broken formula break commands. But do complain.
// 2622:       onoe "Failed to import: #{name_or_file}"
// 2623:       $stderr.puts e
// 2624:
// 2625:       nil
// 2626:     end
// 2627:   end
