// 2839:     cache_key = "#{full_name}-#{read_from_tab}-#{undeclared}"
// 2840:
// 2841:     Formula.cache[:runtime_dependencies] ||= {}
// 2842:     Formula.cache[:runtime_dependencies][cache_key] ||= begin
// 2843:       deps = if read_from_tab && undeclared &&
// 2844:                 (tab_deps = any_installed_keg&.runtime_dependencies)
// 2845:         tab_deps.filter_map do |d|
// 2846:           full_name = d["full_name"]
// 2847:           next unless full_name
// 2848:
// 2849:           Dependency.new full_name
// 2850:         end
// 2851:       end
// 2852:       begin
// 2853:         deps ||= declared_runtime_dependencies unless undeclared
// 2854:         deps ||= (declared_runtime_dependencies | undeclared_runtime_dependencies)
// 2855:       rescue FormulaUnavailableError
// 2856:         onoe "Could not get runtime dependencies from #{path}!"
// 2857:         deps ||= []
// 2858:       end
// 2859:       deps
// 2860:     end
// 2861:   end
