// 2870:       read_from_tab:,
// 2871:       undeclared:,
// 2872:     ).filter_map do |d|
// 2873:       d.to_formula
// 2874:     rescue FormulaUnavailableError
// 2875:       nil
// 2876:     end
// 2877:   end
