// 2881:   def installed_runtime_formula_dependencies(read_from_tab: true, undeclared: true)
// 2882:     cache_key = "#{full_name}-#{read_from_tab}-#{undeclared}"
// 2883:
// 2884:     Formula.cache[:installed_runtime_formula_dependencies] ||= {}
// 2885:     Formula.cache[:installed_runtime_formula_dependencies][cache_key] ||= runtime_dependencies(
// 2886:       read_from_tab:,
// 2887:       undeclared:,
// 2888:     ).filter_map do |d|
