// 2895:   sig { returns(T::Array[Formula]) }
// 2896:   def runtime_installed_formula_dependents
// 2897:     # `any_installed_keg` and `runtime_dependencies` `select`s ensure
// 2898:     # that we don't end up with something `Formula#runtime_dependencies` can't
// 2899:     # read from a `Tab`.
// 2900:     Formula.cache[:runtime_installed_formula_dependents] ||= {}
// 2901:     Formula.cache[:runtime_installed_formula_dependents][full_name] ||= Formula.installed
// 2902:                                                                                .select(&:any_installed_keg)
// 2903:                                                                                .select(&:runtime_dependencies)
// 2904:                                                                                .select do |f|
// 2905:       f.installed_runtime_formula_dependencies.any? do |dep|
// 2906:         full_name == dep.full_name
// 2907:       rescue
// 2908:         name == dep.name
// 2909:       end
// 2910:     end
// 2911:   end
// 2912:
// 2913:   # Returns a list of formulae depended on by this formula that aren't
// 2914:   # installed. Only trusts tab data for dependency information; when the tab
// 2915:   # has no runtime dependency data (nil or empty), returns empty rather
// 2916:   # than falling back to formula definitions.
// 2917:   # This prevents stale or missing tab data from incorrectly blocking
// 2918:   # uninstalls.
// 2919:   sig { params(hide: T::Array[String]).returns(T::Array[Dependency]) }
// 2920:   def missing_dependencies(hide: [])
// 2921:     tab_deps = any_installed_keg&.runtime_dependencies
// 2922:     return [] if tab_deps.blank?
// 2923:
// 2924:     tab_deps.filter_map do |d|
// 2925:       full_name = d["full_name"]
// 2926:       next if full_name.blank?
// 2927:
// 2928:       # Use base name to check the cellar directly, avoiding Formulary.resolve.
// 2929:       # A dep is "missing" if it's in the hide list (pretend uninstalled) or
// 2930:       # genuinely not installed in the cellar.
// 2931:       base_name = Utils.name_from_full_name(full_name)
// 2932:       next if hide.exclude?(base_name) && ((HOMEBREW_CELLAR/base_name).directory? ||
// 2933:                                            (HOMEBREW_PREFIX/"opt"/base_name).directory?)
// 2934:
// 2935:       Dependency.new(full_name)
// 2936:     end
// 2937:   end
