// 3171:         h["directory"] = external.resource.directory.to_s if external.resource.directory.present?
// 3172:         h["type"] = external.type.to_s.tr("_", "-") if external.type
// 3173:         resolves = external.resolves
// 3174:         h["resolves"] = resolves.map { |id| { "type" => Patch.resolves_type(id), "id" => id } } if resolves.any?
// 3175:       elsif p.is_a?(LocalPatch)
