// 3358:
// 3359:   # This method is overridden in {Formula} subclasses to provide the
// 3360:   # installation instructions. The sources (from {.url}) are downloaded,
// 3361:   # hash-checked and then Homebrew changes into a temporary directory where the
// 3362:   # archive is unpacked or repository cloned.
// 3363:   #
// 3364:   # ### Example
// 3365:   #
// 3366:   # ```ruby
// 3367:   # def install
// 3368:   #   system "./configure", "--prefix=#{prefix}"
// 3369:   #   system "make", "install"
// 3370:   # end
// 3371:   # ```
// 3372:   #
// 3373:   # @api public
// 3374:   sig { void }
// 3375:   def install; end
// 3376:
// 3377:   # Sometimes we have to change a bit before we install. Mostly we
// 3378:   # prefer a patch, but if you need the {Formula#prefix prefix} of
// 3379:   # this formula in the patch you have to resort to `inreplace`,
// 3380:   # because in the patch you don't have access to any variables
// 3381:   # defined by the formula, as only `HOMEBREW_PREFIX` is available
// 3382:   # in the {DATAPatch embedded patch}.
// 3383:   #
// 3384:   # ### Examples
// 3385:   #
// 3386:   # `inreplace` supports regular expressions:
// 3387:   #
// 3388:   # ```ruby
// 3389:   # inreplace "somefile.cfg", /look[for]what?/, "replace by #{bin}/tool"
// 3390:   # ```
// 3391:   #
// 3392:   # `inreplace` supports blocks:
// 3393:   #
// 3394:   # ```ruby
// 3395:   # inreplace "Makefile" do |s|
// 3396:   #   s.gsub! "/usr/local", HOMEBREW_PREFIX.to_s
// 3397:   # end
// 3398:   # ```
// 3399:   #
// 3400:   # @see Utils::Inreplace.inreplace
// 3401:   # @api public
// 3402:   sig {
// 3403:     params(
// 3404:       paths:        T.any(T::Enumerable[T.any(String, Pathname)], String, Pathname),
// 3405:       before:       T.nilable(T.any(Pathname, Regexp, String)),
// 3406:       after:        T.nilable(T.any(Pathname, String, Symbol)),
// 3407:       audit_result: T::Boolean,
// 3408:       global:       T::Boolean,
// 3409:       block:        T.nilable(T.proc.params(s: StringInreplaceExtension).void),
// 3410:     ).void
// 3411:   }
// 3412:   def inreplace(paths, before = nil, after = nil, audit_result: true, global: true, &block)
// 3413:     Utils::Inreplace.inreplace(paths, before, after, audit_result:, global:, &block)
// 3414:   rescue Utils::Inreplace::Error => e
// 3415:     onoe e.to_s
// 3416:     raise BuildError.new(self, "inreplace", Array(paths), {})
// 3417:   end
