// 3429:   def declared_runtime_dependencies
// 3430:     cache_key = "Formula#declared_runtime_dependencies"
// 3431:     if build.any_args_or_options?
// 3432:       cache_key += "-#{full_name}"
// 3433:       cache_timestamp = Time.now
// 3434:     end
// 3435:     Dependency.expand(self, cache_key:, cache_timestamp:) do |_, dependency|
// 3436:       next Dependable::PRUNE if dependency.build?
// 3437:       next if dependency.required?
// 3438:
// 3439:       if build.any_args_or_options?
// 3440:         next Dependable::PRUNE if build.without?(dependency)
// 3441:       elsif !dependency.recommended?
// 3442:         next Dependable::PRUNE
// 3443:       end
// 3444:     end
// 3445:   ensure
// 3446:     Dependency.delete_timestamped_cache_entry(cache_key, cache_timestamp) if build.any_args_or_options?
// 3447:   end
