// 3457:       typed_db = T.cast(db, CacheStoreDatabase[String, T::Hash[T.any(String, Symbol), T.anything]])
// 3458:       linkage_checker = LinkageChecker.new(keg, self, cache_db: typed_db)
// 3459:       linkage_checker.undeclared_deps.map { |n| Dependency.new(n) }
