// 3472:       linkage_checker = LinkageChecker.new(keg, self, cache_db: typed_db)
// 3473:       own_libraries = (linkage_checker.broken_deps.fetch(name, []) + linkage_checker.broken_dylibs.to_a).uniq.sort
// 3474:       dependency_names = linkage_checker.broken_deps.keys.reject { |dep| dep == name }.to_set
