// 3478:
// 3479:   # To call out to the system, we use the `system` method and we prefer
// 3480:   # you give the args separately as in the line below, otherwise a subshell
// 3481:   # has to be opened first.
// 3482:   #
// 3483:   # ### Examples
// 3484:   #
// 3485:   # ```ruby
// 3486:   # system "./bootstrap.sh", "--arg1", "--prefix=#{prefix}"
// 3487:   # ```
// 3488:   #
// 3489:   # For CMake and other build systems we have some necessary defaults in e.g.
// 3490:   # {#std_cmake_args}:
// 3491:   #
// 3492:   # ```ruby
// 3493:   # system "cmake", ".", *std_cmake_args
// 3494:   # ```
// 3495:   #
// 3496:   # If the arguments given to `configure` (or `make` or `cmake`) are depending
// 3497:   # on options defined above, we usually make a list first and then
// 3498:   # use the `args << if <condition>` to append each:
// 3499:   #
// 3500:   # ```ruby
// 3501:   # args = ["--with-option1", "--with-option2"]
// 3502:   # args << "--without-gcc" if ENV.compiler == :clang
// 3503:   # ```
// 3504:   #
// 3505:   # Most software still uses `configure` and `make`.
// 3506:   # Check with `./configure --help` for what our options are.
// 3507:   #
// 3508:   # ```ruby
// 3509:   # system "./configure", "--disable-debug", "--disable-dependency-tracking",
// 3510:   #                       "--disable-silent-rules", "--prefix=#{prefix}",
// 3511:   #                       *args # our custom arg list (needs `*` to unpack)
// 3512:   # ```
// 3513:   #
// 3514:   # If there is a "make install" available, please use it!
// 3515:   #
// 3516:   # ```ruby
// 3517:   # system "make", "install"
// 3518:   # ```
// 3519:   #
// 3520:   # @api public
// 3521:   sig { params(cmd: T.any(String, Pathname), args: T.any(String, Integer, Pathname, Symbol)).void }
// 3522:   def system(cmd, *args)
// 3523:     verbose_using_dots = Homebrew::EnvConfig.verbose_using_dots?
// 3524:
// 3525:     # remove "boring" arguments so that the important ones are more likely to
// 3526:     # be shown considering that we trim long ohai lines to the terminal width
// 3527:     pretty_args = args.dup
// 3528:     unless verbose?
// 3529:       case cmd
// 3530:       when "./configure"
// 3531:         pretty_args -= std_configure_args
// 3532:       when "cabal"
// 3533:         pretty_args -= std_cabal_v2_args
// 3534:       when "cargo"
// 3535:         pretty_args -= std_cargo_args
// 3536:       when "cmake"
// 3537:         pretty_args -= std_cmake_args
// 3538:       when "go"
// 3539:         pretty_args -= std_go_args
// 3540:       when "meson"
// 3541:         pretty_args -= std_meson_args
// 3542:       when "zig"
// 3543:         pretty_args -= std_zig_args
// 3544:       when %r{(^|/)(pip|python)(?:[23](?:\.\d{1,2})?)?$}
// 3545:         pretty_args -= std_pip_args
// 3546:       end
// 3547:     end
// 3548:     pretty_args.each_index do |i|
// 3549:       pretty_args[i] = "import setuptools..." if pretty_args[i].to_s.start_with? "import setuptools"
// 3550:     end
// 3551:     ohai "#{cmd} #{pretty_args * " "}".strip
// 3552:
// 3553:     @exec_count ||= T.let(0, T.nilable(Integer))
// 3554:     @exec_count += 1
// 3555:     log_filename = format("#{logs}/#{active_log_prefix}%02<exec_count>d.%<cmd_base>s.log",
// 3556:                           exec_count: @exec_count,
// 3557:                           cmd_base:   File.basename(cmd).split.first)
// 3558:     logs.mkpath
// 3559:
// 3560:     File.open(log_filename, "w") do |log|
// 3561:       log.puts Time.now, "", cmd, args, ""
// 3562:       log.flush
// 3563:
// 3564:       if verbose?
// 3565:         rd, wr = IO.pipe
// 3566:         begin
// 3567:           pid = fork do
// 3568:             rd.close
// 3569:             log.close
// 3570:             exec_cmd(cmd, args, wr, log_filename)
// 3571:           end
// 3572:           wr.close
// 3573:
// 3574:           if verbose_using_dots
// 3575:             last_dot = Time.at(0)
// 3576:             while (buf = rd.gets)
// 3577:               log.puts buf
// 3578:               # make sure dots printed with interval of at least 1 min.
// 3579:               next if (Time.now - last_dot) <= 60
// 3580:
// 3581:               print "."
// 3582:               $stdout.flush
// 3583:               last_dot = Time.now
// 3584:             end
// 3585:             puts
// 3586:           else
// 3587:             while (buf = rd.gets)
// 3588:               log.puts buf
// 3589:               puts buf
// 3590:             end
// 3591:           end
// 3592:         ensure
// 3593:           rd.close
// 3594:         end
// 3595:       else
// 3596:         pid = fork do
// 3597:           exec_cmd(cmd, args, log, log_filename)
// 3598:         end
// 3599:       end
// 3600:
// 3601:       Process.wait(pid)
// 3602:
// 3603:       $stdout.flush
// 3604:
// 3605:       unless $CHILD_STATUS.success?
// 3606:         log_lines = Homebrew::EnvConfig.fail_log_lines
// 3607:
// 3608:         log.flush
// 3609:         if !verbose? || verbose_using_dots
// 3610:           puts "Last #{log_lines} lines from #{log_filename}:"
// 3611:           Kernel.system "/usr/bin/tail", "-n", log_lines.to_s, log_filename
// 3612:         end
// 3613:         log.puts
// 3614:
// 3615:         require "system_config"
// 3616:         require "build_environment"
// 3617:
// 3618:         env = ENV.to_hash
// 3619:
// 3620:         SystemConfig.dump_verbose_config(log)
// 3621:         log.puts
// 3622:         BuildEnvironment.dump env, log
// 3623:
// 3624:         raise BuildError.new(self, cmd, args, env)
// 3625:       end
// 3626:     end
// 3627:   end
// 3628:
// 3629:   sig { params(quiet: T::Boolean).returns(T::Array[Keg]) }
// 3630:   def eligible_kegs_for_cleanup(quiet: false)
// 3631:     eligible_for_cleanup = []
// 3632:     if latest_version_installed?
// 3633:       eligible_kegs = if head? && (head_prefix = latest_head_prefix)
// 3634:         head, stable = installed_kegs.partition { |keg| keg.version.head? }
// 3635:
// 3636:         # Remove newest head and stable kegs.
// 3637:         head - [Keg.new(head_prefix)] + T.must(stable.sort_by(&:scheme_and_version).slice(0...-1))
// 3638:       else
// 3639:         installed_kegs.select do |keg|
// 3640:           tab = keg.tab
// 3641:           if version_scheme > tab.version_scheme
// 3642:             true
// 3643:           elsif version_scheme == tab.version_scheme
// 3644:             pkg_version > keg.version
// 3645:           else
// 3646:             false
// 3647:           end
// 3648:         end
// 3649:       end
// 3650:
// 3651:       unless eligible_kegs.empty?
// 3652:         eligible_kegs.each do |keg|
// 3653:           if keg.linked?
// 3654:             opoo "Skipping (old) #{keg} due to it being linked" unless quiet
// 3655:           elsif pinned? && keg == Keg.new(@pin.path.resolved_path)
// 3656:             opoo "Skipping (old) #{keg} due to it being pinned" unless quiet
// 3657:           elsif (keepme_refs = keg.keepme_refs.presence)
// 3658:             opoo "Skipping #{keg} as it is needed by #{keepme_refs.join(", ")}" unless quiet
// 3659:           else
// 3660:             eligible_for_cleanup << keg
// 3661:           end
// 3662:         end
// 3663:       end
// 3664:     elsif !installed_prefixes.empty? && !pinned?
// 3665:       # If the rack only has one version installed, don't complain
// 3666:       # that we can't tell which one to keep. Don't complain at all if the
// 3667:       # only installed version is a pinned formula.
// 3668:       opoo "Skipping #{full_name}: most recent version #{pkg_version} not installed" unless quiet
// 3669:     end
// 3670:     eligible_for_cleanup
// 3671:   end
