// 3744:     {
// 3745:       _JAVA_OPTIONS:           "-Duser.home=#{HOMEBREW_CACHE}/java_cache",
// 3746:       GOCACHE:                 "#{HOMEBREW_CACHE}/go_cache",
// 3747:       GIT_CONFIG_GLOBAL:       Utils::Git.no_global_config_file,
