// 3928:
// 3929:     # The SPDX ID of the open-source license that the formula uses.
// 3930:     # Shows when running `brew info`.
// 3931:     #
// 3932:     # Use `:any_of`, `:all_of` or `:with` to describe complex license expressions.
// 3933:     # `:any_of` should be used when the user can choose which license to use.
// 3934:     # `:all_of` should be used when the user must use all licenses.
// 3935:     # `:with` should be used to specify a valid SPDX exception.
// 3936:     #
// 3937:     # Add `+` to an identifier to indicate that the formula can be
// 3938:     # licensed under later versions of the same license.
// 3939:     #
// 3940:     # ### Examples
// 3941:     #
// 3942:     # ```ruby
// 3943:     # license "BSD-2-Clause"
// 3944:     # ```
// 3945:     #
// 3946:     # ```ruby
// 3947:     # license "EPL-1.0+"
// 3948:     # ```
// 3949:     #
// 3950:     # ```ruby
// 3951:     # license any_of: ["MIT", "GPL-2.0-only"]
// 3952:     # ```
// 3953:     #
// 3954:     # ```ruby
// 3955:     # license all_of: ["MIT", "GPL-2.0-only"]
// 3956:     # ```
// 3957:     #
// 3958:     # ```ruby
// 3959:     # license "GPL-2.0-only" => { with: "LLVM-exception" }
// 3960:     # ```
// 3961:     #
// 3962:     # ```ruby
// 3963:     # license :public_domain
// 3964:     # ```
// 3965:     #
// 3966:     # ```ruby
// 3967:     # license any_of: [
// 3968:     #   "MIT",
// 3969:     #   :public_domain,
// 3970:     #   all_of: ["0BSD", "Zlib", "Artistic-1.0+"],
// 3971:     #   "Apache-2.0" => { with: "LLVM-exception" },
// 3972:     # ]
// 3973:     # ```
// 3974:     #
// 3975:     # @see https://docs.brew.sh/Licence-Guidelines Homebrew Licence Guidelines
// 3976:     # @see https://spdx.github.io/spdx-spec/latest/annexes/spdx-license-expressions/ SPDX license expression guide
// 3977:     # @api public
// 3978:     sig {
// 3979:       params(args: T.nilable(SPDX::LicenseExpression))
// 3980:         .returns(T.nilable(SPDX::LicenseExpression))
// 3981:     }
