// 3990:     # The phases for which network access is allowed. By default, network
// 3991:     # access is allowed for all phases. Valid phases are `:build`, `:test`,
// 3992:     # and `:postinstall`. When no argument is passed, network access will be
// 3993:     # allowed for all phases.
// 3994:     #
// 3995:     # ### Examples
// 3996:     #
// 3997:     # ```ruby
// 3998:     # allow_network_access!
// 3999:     # ```
// 4000:     #
// 4001:     # ```ruby
// 4002:     # allow_network_access! :build
// 4003:     # ```
// 4004:     #
// 4005:     # ```ruby
// 4006:     # allow_network_access! [:build, :test]
