// 4009:     # @api public
// 4010:     sig { params(phases: T.any(Symbol, T::Array[Symbol])).void }
// 4011:     def allow_network_access!(phases = [])
// 4012:       phases_array = Array(phases)
// 4013:       if phases_array.empty?
// 4014:         network_access_allowed.each_key { |phase| network_access_allowed[phase] = true }
// 4015:       else
// 4016:         phases_array.each do |phase|
// 4017:           raise ArgumentError, "Unknown phase: #{phase}" unless SUPPORTED_NETWORK_ACCESS_PHASES.include?(phase)
// 4018:
// 4019:           network_access_allowed[phase] = true
// 4020:         end
// 4021:       end
// 4022:     end
