// 4241:     # If not inferable, specify the download strategy with `using: ...`.
// 4242:     #
// 4243:     # - `:git`, `:hg`, `:svn`, `:bzr`, `:fossil`, `:cvs`,
// 4244:     # - `:curl` (normal file download, will also extract)
// 4245:     # - `:homebrew_curl` (use brewed `curl`)
