// 4247:     # - `:post` (download via an HTTP POST request)
// 4248:     #
// 4249:     # ### Examples
// 4250:     #
// 4251:     # ```ruby
// 4252:     # url "https://packed.sources.and.we.prefer.https.example.com/archive-1.2.3.tar.bz2"
