// 4261:     #
// 4262:     # @api public
// 4263:     sig { params(val: String, specs: T::Hash[Symbol, T.anything]).returns(String) }
// 4264:     def url(val = T.unsafe(nil), specs = {}) = stable.url(val, specs)
// 4265:
// 4266:     # The version string for the {.stable} version of the formula.
// 4267:     # The version is autodetected from the URL and/or tag so only needs to be
// 4268:     # declared if it cannot be autodetected correctly.
// 4269:     #
// 4270:     # ### Example
// 4271:     #
// 4272:     # ```ruby
// 4273:     # version "1.2-final"
// 4274:     # ```
// 4275:     #
// 4276:     # @api public
// 4277:     sig { params(val: T.nilable(String)).returns(T.nilable(Version)) }
// 4278:     def version(val = nil) = stable.version(val)
// 4279:
// 4280:     # Additional URLs for the {.stable} version of the formula.
// 4281:     # These are only used if the {.url} fails to download. It's optional and
// 4282:     # there can be more than one. Generally we add them when the main {.url}
// 4283:     # is unreliable. If {.url} is really unreliable then we may swap the
// 4284:     # {.mirror} and {.url}.
// 4285:     #
// 4286:     # ### Example
// 4287:     #
// 4288:     # ```ruby
// 4289:     # mirror "https://in.case.the.host.is.down.example.com"
// 4290:     # mirror "https://in.case.the.mirror.is.down.example.com
// 4291:     # ```
// 4292:     #
// 4293:     # @api public
// 4294:     sig { params(val: String).void }
// 4295:     def mirror(val) = stable.mirror(val)
// 4296:
// 4297:     # @scope class
// 4298:     # To verify the cached download's integrity and security we verify the
// 4299:     # SHA-256 hash matches what we've declared in the {Formula}. To quickly fill
// 4300:     # this value you can leave it blank and run `brew fetch --force` and it'll
// 4301:     # tell you the currently valid value.
// 4302:     #
// 4303:     # ### Example
// 4304:     #
// 4305:     # ```ruby
// 4306:     # sha256 "2a2ba417eebaadcb4418ee7b12fe2998f26d6e6f7fda7983412ff66a741ab6f7"
// 4307:     # ```
// 4308:     #
// 4309:     # @api public
// 4310:     sig { params(val: String).void }
// 4311:     def sha256(val) = stable.sha256(val)
// 4312:
// 4313:     # Adds a {.bottle} {SoftwareSpec}.
// 4314:     # This provides a pre-built binary package built by the Homebrew maintainers for you.
// 4315:     # It will be installed automatically if there is a binary package for your platform
// 4316:     # and you haven't passed or previously used any options on this formula.
// 4317:     #
// 4318:     # If you maintain your own repository, you can add your own bottle links.
// 4319:     # @see https://docs.brew.sh/Bottles Bottles
// 4320:     # You can ignore this block entirely if submitting to Homebrew/homebrew-core.
// 4321:     # It'll be handled for you by the Brew Test Bot.
// 4322:     #
// 4323:     # ```ruby
// 4324:     # bottle do
// 4325:     #   root_url "https://example.com" # Optional root to calculate bottle URLs.
// 4326:     #   rebuild 1 # Marks the old bottle as outdated without bumping the version/revision of the formula.
// 4327:     #   # Optionally specify the HOMEBREW_CELLAR in which the bottles were built.
// 4328:     #   sha256 cellar: "/brew/Cellar", tahoe:    "ef65c759c5097a36323fa9c77756468649e8d1980a3a4e05695c05e39568967c"
// 4329:     #   sha256 cellar: :any,           sequoia:  "28f4090610946a4eb207df102d841de23ced0d06ba31cb79e040d883906dcd4f"
// 4330:     #   sha256                         sonoma:   "91dd0caca9bd3f38c439d5a7b6f68440c4274945615fae035ff0a369264b8a2f"
// 4331:     # end
// 4332:     # ```
// 4333:     #
// 4334:     # Homebrew maintainers aim to bottle all formulae.
// 4335:     #
// 4336:     # @api public
// 4337:     sig { params(block: T.proc.bind(BottleSpecification).void).void }
// 4338:     def bottle(&block) = stable.bottle(&block)
// 4339:
// 4340:     sig { returns(BuildOptions) }
// 4341:     def build = stable.build
// 4342:
// 4343:     # Get the `BUILD_FLAGS` from the formula's namespace set in `Formulary::load_formula`.
// 4344:     sig { returns(T::Array[String]) }
// 4345:     def build_flags
// 4346:       namespace = T.must(to_s.split("::")[0..-2]).join("::")
// 4347:       return [] if namespace.empty?
// 4348:
// 4349:       # The namespace is derived dynamically from the formula's own name.
// 4350:       # rubocop:disable Sorbet/ConstantsFromStrings
// 4351:       mod = const_get(namespace)
// 4352:       mod.const_get(:BUILD_FLAGS)
// 4353:       # rubocop:enable Sorbet/ConstantsFromStrings
// 4354:     end
// 4355:
// 4356:     # Allows adding {.depends_on} and {Patch}es just to the {.stable} {SoftwareSpec}.
// 4357:     # This is required instead of using a conditional.
// 4358:     # It is preferable to also pull the {url} and {sha256} into the block if one is added.
// 4359:     #
// 4360:     # ### Example
// 4361:     #
// 4362:     # ```ruby
// 4363:     # stable do
// 4364:     #   url "https://example.com/foo-1.0.tar.gz"
// 4365:     #   sha256 "2a2ba417eebaadcb4418ee7b12fe2998f26d6e6f7fda7983412ff66a741ab6f7"
// 4366:     #
// 4367:     #   depends_on "libxml2"
// 4368:     #   depends_on "libffi"
// 4369:     # end
// 4370:     # ```
// 4371:     #
// 4372:     # @api public
// 4373:     sig { params(block: T.nilable(T.proc.bind(SoftwareSpec).void)).returns(T.untyped) }
// 4374:     def stable(&block)
// 4375:       return T.must(@stable) unless block
// 4376:
// 4377:       T.must(@stable).instance_eval(&block)
// 4378:     end
// 4379:
// 4380:     # Adds a {.head} {SoftwareSpec}.
// 4381:     # This can be installed by passing the `--HEAD` option to allow
// 4382:     # installing software directly from a branch of a version-control repository.
// 4383:     # If called as a method this provides just the {url} for the {SoftwareSpec}.
// 4384:     # If a block is provided you can also add {.depends_on} and {Patch}es just to the {.head} {SoftwareSpec}.
// 4385:     # The download strategies (e.g. `:using =>`) are the same as for {url}.
// 4386:     # Git repositories must always specify `branch:`.
// 4387:     #
// 4388:     # ### Example
// 4389:     #
// 4390:     # ```ruby
// 4391:     # head "https://we.prefer.https.over.git.example.com/.git", branch: "main"
// 4392:     # ```
// 4393:     #
// 4394:     # ```ruby
// 4395:     # head "https://example.com/.git", branch: "name_of_branch"
// 4396:     # ```
// 4397:     #
// 4398:     # or (if autodetect fails):
// 4399:     #
// 4400:     # ```ruby
// 4401:     # head "https://hg.is.awesome.but.git.has.won.example.com/", using: :hg
// 4402:     # ```
// 4403:     #
// 4404:     # @api public
// 4405:     sig {
// 4406:       params(
// 4407:         val:   T.nilable(String),
// 4408:         specs: T::Hash[Symbol, T.untyped],
// 4409:         block: T.nilable(T.proc.bind(SoftwareSpec).void),
// 4410:       ).returns(
// 4411:         T.untyped,
// 4412:       )
// 4413:     }
// 4414:     def head(val = nil, specs = {}, &block)
// 4415:       if block
// 4416:         T.must(@head).instance_eval(&block)
// 4417:       elsif val
// 4418:         T.must(@head).url(val, specs)
// 4419:       else
// 4420:         @head
// 4421:       end
// 4422:     end
// 4423:
// 4424:     # Adds information about PyPI formula mapping as {PypiPackages} object.
// 4425:     # It provides a way to specify package name in PyPI repository,
// 4426:     # define extra packages, or remove them (e.g. if formula installs them as a dependency).
// 4427:     #
// 4428:     # Examples of usage:
// 4429:     # ```rb
// 4430:     # # It will use information about the PyPI package `foo` to update resources
// 4431:     # pypi_packages package_name: "foo"
// 4432:     #
// 4433:     # Add "extra" packages and remove unneeded ones
// 4434:     # depends_on "numpy"
// 4435:     #
// 4436:     # pypi_packages extra_packages: "setuptools", exclude_packages: "numpy"
// 4437:     #
// 4438:     # # Special case: empty `package_name` allows to skip resource updates for non-extra packages
// 4439:     # pypi_packages package_name: "", extra_packages: "setuptools"
// 4440:     # ```
// 4441:     #
// 4442:     # @api public
// 4443:     sig {
// 4444:       params(
// 4445:         package_name:     T.nilable(String),
// 4446:         extra_packages:   T.nilable(T.any(String, T::Array[String])),
// 4447:         exclude_packages: T.nilable(T.any(String, T::Array[String])),
// 4448:         dependencies:     T.nilable(T.any(String, T::Array[String])),
// 4449:       ).void
// 4450:     }
// 4451:     def pypi_packages(
// 4452:       package_name: nil,
// 4453:       extra_packages: nil,
// 4454:       exclude_packages: nil,
// 4455:       dependencies: nil
// 4456:     )
// 4457:       if [package_name, extra_packages, exclude_packages, dependencies].all?(&:nil?)
// 4458:         raise ArgumentError, "must provide at least one argument"
// 4459:       end
// 4460:
// 4461:       # Sadly `v1, v2, v3 = [v1, v2, v3].map { |x| Array(x) }` does not work
// 4462:       # for typechecker
// 4463:       extra_packages = Array(extra_packages)
// 4464:       exclude_packages = Array(exclude_packages)
// 4465:       dependencies = Array(dependencies)
// 4466:
// 4467:       @pypi_packages_info = PypiPackages.new(package_name:, extra_packages:, exclude_packages:, dependencies:)
// 4468:     end
// 4469:
// 4470:     # Additional downloads can be defined as {resource}s and accessed in the
// 4471:     # install method. Resources can also be defined inside a {.stable} or
// 4472:     # {.head} block. This mechanism replaces ad-hoc "subformula" classes.
// 4473:     #
// 4474:     # ### Example
// 4475:     #
// 4476:     # ```ruby
// 4477:     # resource "additional_files" do
// 4478:     #   url "https://example.com/additional-stuff.tar.gz"
// 4479:     #   sha256 "c6bc3f48ce8e797854c4b865f6a8ff969867bbcaebd648ae6fd825683e59fef2"
// 4480:     # end
// 4481:     # ```
// 4482:     #
// 4483:     # @api public
// 4484:     sig { params(name: String, klass: T.class_of(Resource), block: T.nilable(T.proc.bind(Resource).void)).void }
// 4485:     def resource(name, klass = Resource, &block)
// 4486:       specs.each do |spec|
// 4487:         spec.resource(name, klass, &block) unless spec.resource_defined?(name)
// 4488:       end
// 4489:     end
// 4490:
// 4491:     # The dependencies for this formula. Use strings for the names of other
// 4492:     # formulae. Homebrew provides some `:special` {Requirement}s for stuff
// 4493:     # that needs extra handling (often changing some ENV vars or
// 4494:     # deciding whether to use the system provided version).
// 4495:     #
// 4496:     # ### Examples
// 4497:     #
// 4498:     # `:build` means this dependency is only needed during build.
// 4499:     #
// 4500:     # ```ruby
// 4501:     # depends_on "cmake" => :build
// 4502:     # ```
// 4503:     #
// 4504:     # `:test` means this dependency is only needed during testing.
// 4505:     #
// 4506:     # ```ruby
// 4507:     # depends_on "node" => :test
// 4508:     # ```
// 4509:     #
// 4510:     # `:recommended` dependencies are built by default.
// 4511:     # But a `--without-...` option is generated to opt-out.
// 4512:     #
// 4513:     # ```ruby
// 4514:     # depends_on "readline" => :recommended
// 4515:     # ```
// 4516:     #
// 4517:     # `:optional` dependencies are NOT built by default unless the
// 4518:     # auto-generated `--with-...` option is passed.
// 4519:     #
// 4520:     # ```ruby
// 4521:     # depends_on "glib" => :optional
// 4522:     # ```
// 4523:     #
// 4524:     # If you need to specify that another formula has to be built with/out
// 4525:     # certain options (note, no `--` needed before the option):
// 4526:     #
// 4527:     # ```ruby
// 4528:     # depends_on "zeromq" => "with-pgm"
// 4529:     # depends_on "qt" => ["with-qtdbus", "developer"] # Multiple options.
// 4530:     # ```
// 4531:     #
// 4532:     # Optional and enforce that "boost" is built using `--with-c++11`.
// 4533:     #
// 4534:     # ```ruby
// 4535:     # depends_on "boost" => [:optional, "with-c++11"]
// 4536:     # ```
// 4537:     #
// 4538:     # If a dependency is only needed in certain cases:
// 4539:     #
// 4540:     # ```ruby
// 4541:     # depends_on xcode: :build # If the formula really needs full Xcode to compile.
// 4542:     # depends_on macos: :sequoia # Needs at least macOS Sequoia (15) to run.
// 4543:     # on_tahoe :or_newer do
// 4544:     #   depends_on "sqlite"
// 4545:     # end
// 4546:     # ```
// 4547:     #
// 4548:     # It is possible to only depend on something if
// 4549:     # `build.with?` or `build.without? "another_formula"`:
// 4550:     #
// 4551:     # ```ruby
// 4552:     # depends_on "postgresql" if build.without? "sqlite"
// 4553:     # ```
// 4554:     #
// 4555:     # @api public
// 4556:     sig { params(dep: T.any(String, Symbol, T::Hash[T.any(String, Symbol, T::Class[Requirement]), T.untyped], T::Class[Requirement])).void }
// 4557:     def depends_on(dep)
// 4558:       set_in_block = instance_variable_get(:@called_in_on_system_block) == true
// 4559:       specs.each { |spec| spec.depends_on(dep, set_in_block:) }
// 4560:     end
// 4561:
// 4562:     # Indicates use of dependencies provided by macOS.
// 4563:     # On macOS this is a no-op (as we use the provided system libraries) unless
// 4564:     # `:since` specifies a minimum macOS version.
// 4565:     # On Linux this will act as {.depends_on}.
// 4566:     #
// 4567:     # @api public
// 4568:     sig {
// 4569:       params(
// 4570:         dep:    T.any(String, T::Hash[T.any(String, Symbol), T.any(Symbol, T::Array[Symbol])]),
// 4571:         bounds: T::Hash[Symbol, Symbol],
// 4572:       ).void
// 4573:     }
// 4574:     def uses_from_macos(dep, bounds = {})
// 4575:       specs.each { |spec| spec.uses_from_macos(dep, bounds) }
// 4576:     end
// 4577:
// 4578:     # Options can be used as arguments to `brew install`.
// 4579:     # To switch features on/off: `"with-something"` or `"with-otherthing"`.
// 4580:     # To use other software: `"with-other-software"` or `"without-foo"`.
// 4581:     # Note that for {.depends_on} that are `:optional` or `:recommended`, options
// 4582:     # are generated automatically.
// 4583:     #
// 4584:     # ### Examples
// 4585:     #
// 4586:     # ```ruby
// 4587:     # option "with-spam", "The description goes here without a dot at the end"
// 4588:     # ```
// 4589:     #
// 4590:     # ```ruby
// 4591:     # option "with-qt", "Text here overwrites what's autogenerated by 'depends_on "qt" => :optional'"
// 4592:     # ```
// 4593:     #
// 4594:     # @api public
// 4595:     sig { params(name: String, description: String).void }
// 4596:     def option(name, description = "")
// 4597:       specs.each { |spec| spec.option(name, description) }
// 4598:     end
// 4599:
// 4600:     # Deprecated options are used to rename options and migrate users who used
// 4601:     # them to newer ones. They are mostly used for migrating non-`with` options
// 4602:     # (e.g. `enable-debug`) to `with` options (e.g. `with-debug`).
// 4603:     #
// 4604:     # ### Example
// 4605:     #
// 4606:     # ```ruby
// 4607:     # deprecated_option "enable-debug" => "with-debug"
// 4608:     # ```
// 4609:     #
// 4610:     # @api public
// 4611:     sig { params(hash: T::Hash[String, String]).void }
// 4612:     def deprecated_option(hash)
// 4613:       specs.each { |spec| spec.deprecated_option(hash) }
// 4614:     end
// 4615:
// 4616:     # External patches can be declared using resource-style blocks.
// 4617:     #
// 4618:     # ### Examples
// 4619:     #
// 4620:     # ```ruby
// 4621:     # patch do
// 4622:     #   url "https://example.com/example_patch.diff"
// 4623:     #   sha256 "c6bc3f48ce8e797854c4b865f6a8ff969867bbcaebd648ae6fd825683e59fef2"
// 4624:     # end
// 4625:     # ```
// 4626:     #
// 4627:     # A strip level of `-p1` is assumed. It can be overridden using a symbol
// 4628:     # argument:
// 4629:     #
// 4630:     # ```ruby
// 4631:     # patch :p0 do
// 4632:     #   url "https://example.com/example_patch.diff"
// 4633:     #   sha256 "c6bc3f48ce8e797854c4b865f6a8ff969867bbcaebd648ae6fd825683e59fef2"
// 4634:     # end
// 4635:     # ```
// 4636:     #
// 4637:     # Patches can be declared in stable and head blocks. This form is
// 4638:     # preferred over using conditionals.
// 4639:     #
// 4640:     # ```ruby
// 4641:     # stable do
// 4642:     #   patch do
// 4643:     #     url "https://example.com/example_patch.diff"
// 4644:     #     sha256 "c6bc3f48ce8e797854c4b865f6a8ff969867bbcaebd648ae6fd825683e59fef2"
// 4645:     #   end
// 4646:     # end
// 4647:     # ```
// 4648:     #
// 4649:     # Embedded (`__END__`) patches are declared like so:
// 4650:     #
// 4651:     # ```ruby
// 4652:     # patch :DATA
// 4653:     # patch :p0, :DATA
// 4654:     # ```
// 4655:     #
// 4656:     # Patches can also be embedded by passing a string. This makes it possible
// 4657:     # to provide multiple embedded patches while making only some of them
// 4658:     # conditional.
// 4659:     #
// 4660:     # ```ruby
// 4661:     # patch :p0, "..."
// 4662:     # ```
// 4663:     #
// 4664:     # @see https://docs.brew.sh/Formula-Cookbook#patches Patches
// 4665:     # @api public
// 4666:     sig {
// 4667:       params(
// 4668:         strip: T.any(String, Symbol),
// 4669:         src:   T.nilable(T.any(String, Symbol)),
// 4670:         block: T.nilable(T.proc.bind(Resource::Patch).void),
// 4671:       ).void
// 4672:     }
// 4673:     def patch(strip = :p1, src = nil, &block)
// 4674:       specs.each { |spec| spec.patch(strip, src, &block) }
// 4675:     end
// 4676:
// 4677:     # One or more formulae that conflict with this one and why.
// 4678:     #
// 4679:     # ### Example
// 4680:     #
// 4681:     # ```ruby
// 4682:     # conflicts_with "imagemagick", because: "both install `convert` binaries"
// 4683:     # ```
// 4684:     #
// 4685:     # @api public
// 4686:     sig { params(names: T.untyped).void }
// 4687:     def conflicts_with(*names)
// 4688:       opts = T.let(names.last.is_a?(Hash) ? names.pop : {}, T::Hash[Symbol, T.untyped])
// 4689:       names.each { |name| T.must(conflicts) << FormulaConflict.new(name, opts[:because]) }
// 4690:     end
// 4691:
// 4692:     # Skip cleaning paths in a formula.
// 4693:     #
// 4694:     # Sometimes the formula {Cleaner cleaner} breaks things.
// 4695:     #
// 4696:     # ### Examples
// 4697:     #
// 4698:     # Preserve cleaned paths with:
// 4699:     #
// 4700:     # ```ruby
// 4701:     # skip_clean "bin/foo", "lib/bar"
// 4702:     # ```
// 4703:     #
// 4704:     # Keep .la files with:
// 4705:     #
// 4706:     # ```ruby
// 4707:     # skip_clean :la
// 4708:     # ```
// 4709:     #
// 4710:     # @api public
// 4711:     sig { params(paths: T.any(String, Symbol)).returns(T::Set[T.any(String, Symbol)]) }
// 4712:     def skip_clean(*paths)
// 4713:       paths.flatten!
// 4714:       # Specifying :all is deprecated and will become an error
// 4715:       T.must(skip_clean_paths).merge(paths)
// 4716:     end
// 4717:
// 4718:     # Preserve `@rpath` install names when fixing dynamic linkage on macOS.
// 4719:     #
// 4720:     # By default, Homebrew rewrites library install names (including those starting
// 4721:     # with `@rpath`) to use absolute paths. This can break tools like `macdeployqt`
// 4722:     # that expect `@rpath`-based install names to remain unchanged.
// 4723:     #
// 4724:     # Call this method to skip rewriting install names that start with `@rpath`.
// 4725:     #
// 4726:     # ### Example
// 4727:     #
// 4728:     # ```ruby
// 4729:     # preserve_rpath
// 4730:     # ```
// 4731:     #
// 4732:     # @api public
// 4733:     sig { params(value: T::Boolean).returns(T::Boolean) }
// 4734:     def preserve_rpath(value: true)
// 4735:       @preserve_rpath = value
// 4736:     end
// 4737:
// 4738:     # Check if `@rpath` install names should be preserved.
// 4739:     #
// 4740:     # @api internal
// 4741:     sig { returns(T::Boolean) }
// 4742:     def preserve_rpath?
// 4743:       @preserve_rpath == true
// 4744:     end
// 4745:
// 4746:     # Software that will not be symlinked into the `brew --prefix` and will
// 4747:     # only live in its Cellar. Other formulae can depend on it and Homebrew
// 4748:     # will add the necessary includes, libraries and other paths while
// 4749:     # building that other formula.
// 4750:     #
// 4751:     # Keg-only formulae are not in your PATH and are not seen by compilers
// 4752:     # if you build your own software outside of Homebrew. This way, we
// 4753:     # don't shadow software provided by macOS.
// 4754:     #
// 4755:     # ### Examples
// 4756:     #
// 4757:     # ```ruby
// 4758:     # keg_only :provided_by_macos
// 4759:     # ```
// 4760:     #
// 4761:     # ```ruby
// 4762:     # keg_only :versioned_formulae
// 4763:     # ```
// 4764:     #
// 4765:     # ```ruby
// 4766:     # keg_only "because I want it so"
// 4767:     # ```
// 4768:     #
// 4769:     # @api public
// 4770:     sig { params(reason: T.any(String, Symbol), explanation: String).void }
// 4771:     def keg_only(reason, explanation = "")
// 4772:       @keg_only_reason = T.let(KegOnlyReason.new(reason, explanation), T.nilable(KegOnlyReason))
// 4773:     end
// 4774:
// 4775:     # Marks the {Formula} as failing with a particular compiler so it will fall back to others.
// 4776:     #
// 4777:     # ### Examples
// 4778:     #
// 4779:     # For Apple compilers, this should be in the format:
// 4780:     #
// 4781:     # ```ruby
// 4782:     # fails_with :clang do
// 4783:     #   build 600
// 4784:     #   cause "multiple configure and compile errors"
// 4785:     # end
// 4786:     # ```
// 4787:     #
// 4788:     # The block may be omitted and if present, the build may be omitted;
// 4789:     # if so, then the compiler will not be allowed for *all* versions.
// 4790:     #
// 4791:     # `major_version` should be the major release number only, for instance
// 4792:     # '7' for the GCC 7 series (7.0, 7.1, etc.).
// 4793:     # If `version` or the block is omitted, then the compiler will
// 4794:     # not be allowed for all compilers in that series.
// 4795:     #
// 4796:     # For example, if a bug is only triggered on GCC 7.1 but is not
// 4797:     # encountered on 7.2:
// 4798:     #
// 4799:     # ```ruby
// 4800:     # fails_with gcc: "7" do
// 4801:     #   version "7.1"
// 4802:     # end
// 4803:     # ```
// 4804:     #
// 4805:     # @api public
// 4806:     sig { params(compiler: T.any(Symbol, T::Hash[Symbol, String]), block: T.nilable(T.proc.void)).void }
// 4807:     def fails_with(compiler, &block)
// 4808:       specs.each { |spec| spec.fails_with(compiler, &block) }
// 4809:     end
// 4810:
// 4811:     # A test is required for new formulae and makes us happy.
// 4812:     #
// 4813:     # The block will create, run in and delete a temporary directory.
// 4814:     #
// 4815:     # We want tests that don't require any user input
// 4816:     # and test the basic functionality of the application.
// 4817:     # For example, `foo build-foo input.foo` is a good test
// 4818:     # and `foo --version` or `foo --help` are bad tests.
// 4819:     # However, a bad test is better than no test at all.
// 4820:     #
// 4821:     # ### Examples
// 4822:     #
// 4823:     # ```ruby
// 4824:     # (testpath/"test.file").write <<~EOS
// 4825:     #   writing some test file, if you need to
// 4826:     # EOS
// 4827:     # assert_equal "OK", shell_output("test_command test.file").strip
// 4828:     # ```
// 4829:     #
// 4830:     # Need complete control over stdin, stdout?
// 4831:     #
// 4832:     # ```ruby
// 4833:     # require "open3"
// 4834:     # Open3.popen3("#{bin}/example", "argument") do |stdin, stdout, _|
// 4835:     #   stdin.write("some text")
// 4836:     #   stdin.close
// 4837:     #   assert_equal "result", stdout.read
// 4838:     # end
// 4839:     # ```
// 4840:     #
// 4841:     # The test will fail if it returns false, or if an exception is raised.
// 4842:     # Failed assertions and failed `system` commands will raise exceptions.
// 4843:     #
// 4844:     # @see https://docs.brew.sh/Formula-Cookbook#add-a-test-to-the-formula Tests
// 4845:     # @api public
// 4846:     sig {
// 4847:       # TODO: replace `returns(BasicObject)` with `void` after dropping `return false` handling in test
// 4848:       params(block: T.proc.returns(BasicObject)).returns(BasicObject)
// 4849:     }
// 4850:     def test(&block) = define_method(:test, &block)
// 4851:
// 4852:     # {Livecheck} can be used to check for newer versions of the software.
// 4853:     # This method evaluates the DSL specified in the `livecheck` block of the
// 4854:     # {Formula} (if it exists) and sets the instance variables of a {Livecheck}
// 4855:     # object accordingly. This is used by `brew livecheck` to check for newer
// 4856:     # versions of the software.
// 4857:     #
// 4858:     # ### Example
// 4859:     #
// 4860:     # ```ruby
// 4861:     # livecheck do
// 4862:     #   skip "Not maintained"
// 4863:     #   url "https://example.com/foo/releases"
// 4864:     #   regex /foo-(\d+(?:\.\d+)+)\.tar/
// 4865:     # end
// 4866:     # ```
// 4867:     #
// 4868:     # @api public
// 4869:     sig { params(block: T.nilable(T.proc.bind(Livecheck).returns(T.untyped))).returns(T.untyped) }
// 4870:     def livecheck(&block)
// 4871:       return @livecheck unless block
// 4872:
// 4873:       @livecheck_defined = T.let(true, T.nilable(T::Boolean))
// 4874:       @livecheck.instance_eval(&block)
// 4875:     end
// 4876:
// 4877:     # Exclude the formula from the autobump list.
// 4878:     #
// 4879:     # @api public
// 4880:     sig { params(because: T.any(String, Symbol)).void }
// 4881:     def no_autobump!(because:)
// 4882:       caller_path = caller_locations(1, 1)&.first&.path
// 4883:       if caller_path
// 4884:         tap = Tap.from_path(caller_path)
// 4885:         raise ArgumentError, "no_autobump! can only be used in official Homebrew taps." if tap && !tap.official?
// 4886:       end
// 4887:
// 4888:       if because.is_a?(Symbol) && !NO_AUTOBUMP_REASONS_LIST.key?(because)
// 4889:         raise ArgumentError, "'because' argument should use valid symbol or a string!"
// 4890:       end
// 4891:
// 4892:       odisabled "no_autobump! because: :requires_manual_review" if because == :requires_manual_review
// 4893:
// 4894:       @no_autobump_defined = T.let(true, T.nilable(T::Boolean))
// 4895:       @no_autobump_message = T.let(because, T.nilable(T.any(String, Symbol)))
// 4896:       @autobump = T.let(false, T.nilable(T::Boolean))
// 4897:     end
// 4898:
// 4899:     # Is the formula in the autobump list?
// 4900:     sig { returns(T::Boolean) }
// 4901:     def autobump?
// 4902:       @autobump != false # @autobump may be `nil`
// 4903:     end
// 4904:
