// 4908:     # @see .no_autobump!
// 4909:     sig { returns(T.nilable(T.any(String, Symbol))) }
// 4910:     attr_reader :no_autobump_message
// 4911:
// 4912:     # Service can be used to define services.
// 4913:     # This method evaluates the DSL specified in the service block of the
// 4914:     # {Formula} (if it exists) and sets the instance variables of a Service
// 4915:     # object accordingly. This is used by `brew install` to generate a service file.
// 4916:     #
// 4917:     # ### Example
// 4918:     #
// 4919:     # ```ruby
// 4920:     # service do
// 4921:     #   run [opt_bin/"foo"]
// 4922:     # end
// 4923:     # ```
// 4924:     #
// 4925:     # @api public
// 4926:     sig {
// 4927:       params(
// 4928:         block: T.nilable(T.proc.bind(Homebrew::Service).void),
// 4929:       ).returns(
// 4930:         T.nilable(T.proc.void),
// 4931:       )
// 4932:     }
// 4933:     def service(&block)
// 4934:       return @service_block unless block
// 4935:
// 4936:       @service_block = T.let(block, T.nilable(T.proc.void))
// 4937:     end
// 4938:
// 4939:     # Defines whether the {Formula}'s bottle can be used on the given Homebrew
// 4940:     # installation.
// 4941:     #
// 4942:     # ### Examples
// 4943:     #
// 4944:     # If the bottle requires the Xcode CLT to be installed a
// 4945:     # {Formula} would declare:
// 4946:     #
// 4947:     # ```ruby
// 4948:     # pour_bottle? do
// 4949:     #   reason "The bottle needs the Xcode CLT to be installed."
// 4950:     #   satisfy { MacOS::CLT.installed? }
// 4951:     # end
// 4952:     # ```
// 4953:     #
// 4954:     # If `satisfy` returns `false` then a bottle will not be used and instead
// 4955:     # the {Formula} will be built from source and `reason` will be printed.
// 4956:     #
// 4957:     # Alternatively, a preset reason can be passed as a symbol:
// 4958:     #
// 4959:     # ```ruby
// 4960:     # pour_bottle? only_if: :clt_installed
// 4961:     # ```
// 4962:     #
// 4963:     # @api public
// 4964:     sig {
// 4965:       params(
// 4966:         only_if: T.nilable(Symbol),
// 4967:         block:   T.nilable(T.proc.bind(PourBottleCheck).params(arg0: T.untyped).void),
// 4968:       ).void
// 4969:     }
// 4970:     def pour_bottle?(only_if: nil, &block)
// 4971:       @pour_bottle_check = T.let(PourBottleCheck.new(self), T.nilable(PourBottleCheck))
// 4972:       @pour_bottle_only_if = T.let(only_if, T.nilable(Symbol))
// 4973:
// 4974:       if only_if.present? && block.present?
// 4975:         raise ArgumentError, "Do not pass both a preset condition and a block to `pour_bottle?`"
// 4976:       end
// 4977:
// 4978:       bottle_check_block = block || case only_if
// 4979:       when :clt_installed
// 4980:         lambda do |_|
// 4981:           on_macos do
// 4982:             T.bind(self, PourBottleCheck)
// 4983:             reason(+<<~EOS)
// 4984:               The bottle needs the Xcode Command Line Tools to be installed at /Library/Developer/CommandLineTools.
// 4985:               Development tools provided by Xcode.app are not sufficient.
// 4986:
// 4987:               You can install the Xcode Command Line Tools, if desired, with:
// 4988:                   xcode-select --install
// 4989:             EOS
// 4990:             satisfy { MacOS::CLT.installed? }
// 4991:           end
// 4992:         end
// 4993:       when :default_prefix
// 4994:         lambda do |_|
// 4995:           T.bind(self, PourBottleCheck)
// 4996:           reason(<<~EOS)
// 4997:             The bottle (and many others) needs to be installed into #{Homebrew::DEFAULT_PREFIX}.
// 4998:           EOS
// 4999:           satisfy { HOMEBREW_PREFIX.to_s == Homebrew::DEFAULT_PREFIX }
// 5000:         end
// 5001:       else
// 5002:         raise ArgumentError, "Invalid preset `pour_bottle?` condition" if only_if.present?
// 5003:       end
// 5004:
// 5005:       @pour_bottle_check.instance_eval(&T.unsafe(bottle_check_block))
// 5006:     end
// 5007:
// 5008:     # Deprecates a {Formula} (on the given date) so a warning is
// 5009:     # shown on each installation. If the date has not yet passed the formula
// 5010:     # will not be deprecated.
// 5011:     #
// 5012:     # ### Examples
// 5013:     #
// 5014:     # ```ruby
// 5015:     # deprecate! date: "2020-08-27", because: :unmaintained
// 5016:     # ```
// 5017:     #
// 5018:     # ```ruby
// 5019:     # deprecate! date: "2020-08-27", because: "has been replaced by foo"
// 5020:     # ```
// 5021:     #
// 5022:     # ```ruby
// 5023:     # deprecate! date: "2020-08-27", because: "has been replaced by foo", replacement_formula: "foo"
// 5024:     # ```
// 5025:     # ```ruby
// 5026:     # deprecate! date: "2020-08-27", because: "has been replaced by foo", replacement_cask: "foo"
// 5027:     # ```
// 5028:     # TODO: replace legacy `replacement` with `replacement_formula` or `replacement_cask`
// 5029:     #
// 5030:     # @see https://docs.brew.sh/Deprecating-Disabling-and-Removing#formulae-and-casks
// 5031:     # @see DeprecateDisable::FORMULA_DEPRECATE_DISABLE_REASONS
// 5032:     # @api public
// 5033:     sig {
// 5034:       params(
// 5035:         date:                String,
// 5036:         because:             T.nilable(T.any(String, Symbol)),
// 5037:         replacement:         T.nilable(String),
// 5038:         replacement_formula: T.nilable(String),
// 5039:         replacement_cask:    T.nilable(String),
// 5040:       ).void
// 5041:     }
// 5042:     def deprecate!(date:, because:, replacement: nil, replacement_formula: nil, replacement_cask: nil)
// 5043:       if [replacement, replacement_formula, replacement_cask].filter_map(&:presence).length > 1
// 5044:         raise ArgumentError, "more than one of replacement, replacement_formula and/or replacement_cask specified!"
// 5045:       end
// 5046:
// 5047:       if replacement
// 5048:         odeprecated(
// 5049:           "deprecate!(:replacement)",
// 5050:           "deprecate!(:replacement_formula) or deprecate!(:replacement_cask)",
// 5051:         )
// 5052:       end
// 5053:
// 5054:       @deprecate_args = T.let(
// 5055:         { date:, because:, replacement_formula:, replacement_cask: },
// 5056:         T.nilable(T::Hash[Symbol, T.nilable(T.any(String, Symbol))]),
// 5057:       )
// 5058:
// 5059:       @deprecation_date = T.let(Date.parse(date), T.nilable(Date))
// 5060:       @deprecated = T.let(T.must(@deprecation_date) <= Date.today, T.nilable(T::Boolean))
// 5061:       if @deprecated
// 5062:         @deprecation_reason = T.let(because, T.nilable(T.any(String, Symbol)))
// 5063:         @deprecation_replacement_formula = T.let(replacement_formula.presence || replacement, T.nilable(String))
// 5064:         @deprecation_replacement_cask = T.let(replacement_cask.presence || replacement, T.nilable(String))
// 5065:       else
// 5066:         # Reset these to handle disable! before deprecate!
// 5067:         @deprecation_reason = nil
// 5068:         @deprecation_replacement_formula = nil
// 5069:         @deprecation_replacement_cask = nil
// 5070:       end
// 5071:     end
// 5072:
// 5073:     # Whether this {Formula} is deprecated (i.e. warns on installation).
// 5074:     # Defaults to false.
// 5075:     #
// 5076:     # @see .deprecate!
// 5077:     sig { returns(T::Boolean) }
// 5078:     def deprecated?
// 5079:       @deprecated == true
// 5080:     end
// 5081:
// 5082:     # The date of deprecation of a {Formula}.
// 5083:     #
// 5084:     # @return [nil] if no date is specified.
// 5085:     # @see .deprecate!
// 5086:     sig { returns(T.nilable(Date)) }
// 5087:     attr_reader :deprecation_date
// 5088:
// 5089:     # The reason for deprecation of a {Formula}.
// 5090:     #
// 5091:     # @return [nil] if no reason was provided or the formula is not deprecated.
// 5092:     # @see .deprecate!
// 5093:     sig { returns(T.nilable(T.any(String, Symbol))) }
// 5094:     attr_reader :deprecation_reason
// 5095:
// 5096:     # The replacement formula for a deprecated {Formula}.
// 5097:     #
// 5098:     # @return [nil] if no replacement was provided or the formula is not deprecated.
// 5099:     # @see .deprecate!
// 5100:     sig { returns(T.nilable(String)) }
// 5101:     attr_reader :deprecation_replacement_formula
// 5102:
// 5103:     # The replacement cask for a deprecated {Formula}.
// 5104:     #
// 5105:     # @return [nil] if no replacement was provided or the formula is not deprecated.
// 5106:     # @see .deprecate!
// 5107:     sig { returns(T.nilable(String)) }
// 5108:     attr_reader :deprecation_replacement_cask
// 5109:
// 5110:     # The arguments that were passed to deprecate!.
// 5111:     #
// 5112:     # @return [nil] if deprecate! was not called.
// 5113:     # @see .deprecate!
// 5114:     # @api private
// 5115:     sig { returns(T.nilable(T::Hash[Symbol, T.nilable(T.any(String, Symbol))])) }
// 5116:     attr_reader :deprecate_args
// 5117:
// 5118:     # Disables a {Formula} (on the given date) so it cannot be installed.
// 5119:     # If the date has not yet passed and there is no deprecate! date,
// 5120:     # then the formula will be deprecated.
// 5121:     #
// 5122:     # ### Examples
// 5123:     #
// 5124:     # ```ruby
// 5125:     # disable! date: "2020-08-27", because: :does_not_build
// 5126:     # ```
// 5127:     #
// 5128:     # ```ruby
// 5129:     # disable! date: "2020-08-27", because: "has been replaced by foo"
// 5130:     # ```
// 5131:     #
// 5132:     # ```ruby
// 5133:     # disable! date: "2020-08-27", because: "has been replaced by foo", replacement_formula: "foo"
// 5134:     # ```
// 5135:     # ```ruby
// 5136:     # disable! date: "2020-08-27", because: "has been replaced by foo", replacement_cask: "foo"
// 5137:     # ```
// 5138:     #  TODO: replace legacy `replacement` with `replacement_formula` or `replacement_cask`
// 5139:     #
// 5140:     # @see https://docs.brew.sh/Deprecating-Disabling-and-Removing#formulae-and-casks
// 5141:     # @see DeprecateDisable::FORMULA_DEPRECATE_DISABLE_REASONS
// 5142:     # @api public
// 5143:     sig {
// 5144:       params(
// 5145:         date:                String,
// 5146:         because:             T.nilable(T.any(String, Symbol)),
// 5147:         replacement:         T.nilable(String),
// 5148:         replacement_formula: T.nilable(String),
// 5149:         replacement_cask:    T.nilable(String),
// 5150:       ).void
// 5151:     }
// 5152:     def disable!(date:, because:, replacement: nil, replacement_formula: nil, replacement_cask: nil)
// 5153:       if [replacement, replacement_formula, replacement_cask].filter_map(&:presence).length > 1
// 5154:         raise ArgumentError, "more than one of replacement, replacement_formula and/or replacement_cask specified!"
// 5155:       end
// 5156:
// 5157:       if replacement
// 5158:         odeprecated(
// 5159:           "disable!(:replacement)",
// 5160:           "disable!(:replacement_formula) or disable!(:replacement_cask)",
// 5161:         )
// 5162:       end
// 5163:
// 5164:       @disable_args = T.let(
// 5165:         { date:, because:, replacement_formula:, replacement_cask: },
// 5166:         T.nilable(T::Hash[Symbol, T.nilable(T.any(String, Symbol))]),
// 5167:       )
// 5168:
// 5169:       @disable_date = T.let(Date.parse(date), T.nilable(Date))
// 5170:
// 5171:       if T.must(@disable_date) > Date.today
// 5172:         return if @deprecation_date.present?
// 5173:
// 5174:         @deprecation_reason = T.let(because, T.nilable(T.any(String, Symbol)))
// 5175:         @deprecation_replacement_formula = T.let(replacement_formula.presence || replacement, T.nilable(String))
// 5176:         @deprecation_replacement_cask = T.let(replacement_cask.presence || replacement, T.nilable(String))
// 5177:         @deprecated = T.let(true, T.nilable(T::Boolean))
// 5178:         return
// 5179:       end
// 5180:
// 5181:       @disable_reason = T.let(because, T.nilable(T.any(String, Symbol)))
// 5182:       @disable_replacement_formula = T.let(replacement_formula.presence || replacement, T.nilable(String))
// 5183:       @disable_replacement_cask = T.let(replacement_cask.presence || replacement, T.nilable(String))
// 5184:       @disabled = T.let(true, T.nilable(T::Boolean))
// 5185:     end
// 5186:
// 5187:     # Whether this {Formula} is disabled (i.e. cannot be installed).
// 5188:     # Defaults to false.
// 5189:     #
// 5190:     # @see .disable!
// 5191:     sig { returns(T::Boolean) }
// 5192:     def disabled?
// 5193:       @disabled == true
// 5194:     end
// 5195:
// 5196:     # The date that this {Formula} was or becomes disabled.
// 5197:     # Returns `nil` if no date is specified.
// 5198:     #
// 5199:     # @see .disable!
// 5200:     sig { returns(T.nilable(Date)) }
// 5201:     attr_reader :disable_date
// 5202:
// 5203:     # The reason this {Formula} is disabled.
// 5204:     # Returns `nil` if no reason was provided or the formula is not disabled.
// 5205:     #
// 5206:     # @see .disable!
// 5207:     sig { returns(T.nilable(T.any(String, Symbol))) }
// 5208:     attr_reader :disable_reason
// 5209:
// 5210:     # The replacement formula for a disabled {Formula}.
// 5211:     # Returns `nil` if no reason was provided or the formula is not disabled.
// 5212:     #
// 5213:     # @see .disable!
// 5214:     sig { returns(T.nilable(String)) }
// 5215:     attr_reader :disable_replacement_formula
// 5216:
// 5217:     # The replacement cask for a disabled {Formula}.
// 5218:     # Returns `nil` if no reason was provided or the formula is not disabled.
// 5219:     #
// 5220:     # @see .disable!
// 5221:     sig { returns(T.nilable(String)) }
// 5222:     attr_reader :disable_replacement_cask
// 5223:
// 5224:     # The arguments that were passed to disable!.
// 5225:     #
// 5226:     # @return [nil] if disable! was not called.
// 5227:     # @see .disable!
// 5228:     # @api private
// 5229:     sig { returns(T.nilable(T::Hash[Symbol, T.nilable(T.any(String, Symbol))])) }
// 5230:     attr_reader :disable_args
// 5231:
// 5232:     # Permit overwriting certain files while linking.
// 5233:     #
// 5234:     # ### Examples
// 5235:     #
// 5236:     # Sometimes we accidentally install files outside the prefix. Once we fix that,
// 5237:     # users will get a link conflict error. Overwrite those files with:
// 5238:     #
// 5239:     # ```ruby
// 5240:     # link_overwrite "bin/foo", "lib/bar"
// 5241:     # ```
// 5242:     #
// 5243:     # ```ruby
// 5244:     # link_overwrite "share/man/man1/baz-*"
// 5245:     # ```
// 5246:     sig { params(paths: String).returns(T::Set[String]) }
// 5247:     def link_overwrite(*paths)
// 5248:       paths.flatten!
// 5249:       T.must(link_overwrite_paths).merge(paths)
// 5250:     end
// 5251:
// 5252:     # Returns the major.minor {Version} for the given Python executable,
// 5253:     # as a shorthand for `Language::Python.major_minor_version` in the formula DSL.
// 5254:     #
// 5255:     # @param python [String, Pathname] the Python executable (e.g. `"python3"`)
// 5256:     # @return [Version, nil] the major.minor version, or `nil` when the version cannot be determined
// 5257:     # @api public
// 5258:     sig { params(python: T.any(String, Pathname)).returns(T.nilable(Version)) }
// 5259:     def python_major_minor_version(python)
// 5260:       Language::Python.major_minor_version(python)
// 5261:     end
// 5262:   end
// 5263: end
